fn sum_evens(xs: [Int]) -> Int {
    let mut total = 0
    for x in xs {
        if x % 2 == 0 {
            total = total + x
        }
    }
    return total
}

fn reverse_words(text: String) -> String {
    let words: Vec<String> = text.split(" ").filter(|w| !w.is_empty()).collect();
    let mut result = String::new();
    let mut i = words.len();
    while i > 0 {
        i -= 1;
        if result.len() > 0 {
            result.push_str(" ");
        }
        result.push_str(&words[i]);
    }
    result
}

fn is_palindrome(text: String) -> Bool {
    let s = text.to_lower();
    let n = s.len();
    let mut i = 0;
    while i < n / 2 {
        if s.char_at(i) != s.char_at(n - 1 - i) {
            return false;
        }
        i = i + 1;
    }
    return true;
}

fn count_vowels(text: String) -> Int {
    let mut count: Int = 0;
    for c in text.chars() {
        match c.to_lower() {
            'a' | 'e' | 'i' | 'o' | 'u' => { count += 1; }
            _ => {}
        }
    }
    count
}

fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        return "FizzBuzz"
    } else if n % 3 == 0 {
        return "Fizz"
    } else if n % 5 == 0 {
        return "Buzz"
    } else {
        return n.to_string()
    }
}

fn largest(xs: [Int]) -> Int? {
    if xs.len() == 0 {
        return none
    }
    var best = xs[0]
    for x in xs {
        if x > best {
            best = x
        }
    }
    return best
}

fn word_counts(text: String) -> [String: Int] {
    let counts: [String: Int] = {}
    if text == "" {
        return counts
    }
    for word in text.split(" ") {
        counts[word] = counts.get(word, 0) + 1
    }
    return counts
}

fn doubled(text: String) -> Int ! BadInput {
    match text.toInt() {
        Some(n) => n * 2,
        None => fail NotANumber(text),
    }
}

fn factorial(n: Int) -> Int {
    let mut result: Int = 1;
    let mut i: Int = 2;
    while i <= n {
        result = result * i;
        i = i + 1;
    }
    return result;
}

fn fib(n: Int) -> Int {
    let mut a = 0
    let mut b = 1
    let mut i = 0
    while i < n {
        let t = a + b
        a = b
        b = t
        i = i + 1
    }
    return a
}

fn dedupe(xs: [Int]) -> [Int] {
    let mut result: [Int] = []
    for x in xs {
        let mut seen = false
        for y in result {
            if y == x {
                seen = true
            }
        }
        if !seen {
            result.push(x)
        }
    }
    return result
}

fn total_area(rects: [Rect]) -> Float {
    let mut total = 0.0
    for r in rects {
        total = total + r.width * r.height
    }
    return total
}

fn area(s: Shape) -> Float {
    match s {
        Circle(r) => 3.14 * r * r,
        Square(side) => side * side,
    }
}

fn first_negative(xs: [Int]) -> Int? {
    for i in 0..len(xs) {
        if xs[i] < 0 {
            return i
        }
    }
    return none
}

fn caesar(text: String, k: Int) -> String {
    let mut result = String::new();
    for c in text.chars() {
        if c >= 'a' && c <= 'z' {
            let offset = (c as Int - 'a' as Int + k) % 26;
            result.push(('a' as Int + offset) as Char);
        } else {
            result.push(c);
        }
    }
    result
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let rows = len(m);
    let cols = len(m[0]);
    let mut result: [[Int]] = [];
    for j in 0..cols {
        let mut row: [Int] = [];
        for i in 0..rows {
            row = push(row, m[i][j]);
        }
        result = push(result, row);
    }
    return result;
}

fn find(xs: [Int], target: Int) -> Int? {
    var lo = 0
    var hi = xs.len() - 1
    while lo <= hi {
        let mid = lo + (hi - lo) / 2
        let v = xs[mid]
        if v == target {
            return mid
        } else if v < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return none
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail DivideByZero
    }
    return a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let mut groups: [String: [String]] = {}
    for word in words {
        let letter = word.first_char().to_string()
        if groups.contains_key(letter) {
            groups[letter].push(word)
        } else {
            groups[letter] = [word]
        }
    }
    return groups
}

fn running(xs: [Int]) -> [Int] {
    let mut out: [Int] = []
    let mut total = 0
    for x in xs {
        total = total + x
        out.push(total)
    }
    return out
}

fn gcd(a: Int, b: Int) -> Int {
    let mut x = a
    let mut y = b
    while y != 0 {
        let t = y
        y = x % y
        x = t
    }
    return x
}

fn title(text: String) -> String {
    let mut result = String::new();
    let mut at_word_start = true;
    for c in text.chars() {
        if c == ' ' {
            result.push(c);
            at_word_start = true;
        } else if at_word_start {
            result.push(c.to_uppercase());
            at_word_start = false;
        } else {
            result.push(c.to_lowercase());
        }
    }
    result
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    let mut i = 2
    while i * i <= n {
        if n % i == 0 {
            return false
        }
        i = i + 1
    }
    true
}

fn primes_below(n: Int) -> [Int] {
    let mut primes: [Int] = []
    let mut k: Int = 2
    while k < n {
        let mut is_prime = true
        let mut d: Int = 2
        while d * d <= k {
            if k % d == 0 {
                is_prime = false
                break
            }
            d = d + 1
        }
        if is_prime {
            primes.push(k)
        }
        k = k + 1
    }
    return primes
}

fn digit_sum(n: Int) -> Int {
    let mut total = 0
    let mut m = n
    while m > 0 {
        total = total + m % 10
        m = m / 10
    }
    return total
}

// Note: I'm not certain of Kavach's exact syntax, so this assumes
// Rust-like conventions matching the requested signature.
fn rle(text: String) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut result = String::new();
    let mut i = 0;
    while i < chars.len() {
        let current = chars[i];
        let mut count = 0;
        while i < chars.len() && chars[i] == current {
            count += 1;
            i += 1;
        }
        result.push(current);
        result.push_str(&count.to_string());
    }
    result
}

fn balanced(text: String) -> Bool {
    let mut stack: Vec<String> = Vec::new();
    for c in text.chars() {
        if c == "(" || c == "[" || c == "{" {
            stack.push(c);
        } else if c == ")" || c == "]" || c == "}" {
            if stack.is_empty() {
                return false;
            }
            let top = stack.pop();
            let matches = (c == ")" && top == "(") || (c == "]" && top == "[") || (c == "}" && top == "{");
            if !matches {
                return false;
            }
        }
    }
    return stack.is_empty();
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let n = len(xs)
    for i in 0..n {
        for j in (i + 1)..n {
            if xs[i] + xs[j] == target {
                return Some((i, j))
            }
        }
    }
    return None
}

fn anagrams(a: String, b: String) -> Bool {
    let x = a.to_lower().chars().sort()
    let y = b.to_lower().chars().sort()
    return x == y
}

fn roman(n: i32) -> String {
    let table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ];
    let mut n = n;
    let mut out = String::new();
    for &(v, s) in table.iter() {
        while n >= v {
            out.push_str(s);
            n -= v;
        }
    }
    out
}

fn flatten(xss: [[Int]]) -> [Int] {
    let mut result: [Int] = []
    for xs in xss {
        for x in xs {
            result.push(x)
        }
    }
    return result
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let mut result: [[Int]] = [];
    let len = length(xs);
    let mut i = 0;
    while i < len {
        let end = min(i + n, len);
        result = push(result, slice(xs, i, end));
        i = i + n;
    }
    return result;
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    let n = len(xs)
    if n == 0 {
        return xs
    }
    let s = k % n
    let mut out: [Int] = []
    for i in 0..n {
        out.push(xs[(i + s) % n])
    }
    return out
}

fn common_prefix(words: [String]) -> String {
    if words.len() == 0 {
        return "";
    }
    let mut prefix = words[0].clone();
    for word in words {
        while !word.starts_with(prefix) {
            prefix = prefix.substring(0, prefix.len() - 1);
        }
    }
    return prefix;
}

fn second_largest(xs: [Int]) -> Int? {
    let mut has_first = false
    let mut has_second = false
    let mut first = 0
    let mut second = 0
    for x in xs {
        if has_first && x == first {
            continue
        }
        if !has_first || x > first {
            if has_first {
                second = first
                has_second = true
            }
            first = x
            has_first = true
        } else if !has_second || x > second {
            second = x
            has_second = true
        }
    }
    if has_second {
        return second
    }
    return none
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let mut result: [Int] = []
    let mut i = 0
    let mut j = 0

    while i < len(a) && j < len(b) {
        if a[i] <= b[j] {
            result.push(a[i])
            i = i + 1
        } else {
            result.push(b[j])
            j = j + 1
        }
    }

    while i < len(a) {
        result.push(a[i])
        i = i + 1
    }

    while j < len(b) {
        result.push(b[j])
        j = j + 1
    }

    return result
}

fn distance(a: String, b: String) -> Int {
    let n: Int = a.len();
    let m: Int = b.len();
    let mut prev: Vec<Int> = Vec::new();
    for j in 0..=m {
        prev.push(j);
    }
    for i in 1..=n {
        let mut curr: Vec<Int> = Vec::new();
        curr.push(i);
        for j in 1..=m {
            let cost: Int = if a.char_at(i - 1) == b.char_at(j - 1) { 0 } else { 1 };
            let mut best: Int = prev[j] + 1;
            let ins: Int = curr[j - 1] + 1;
            let sub: Int = prev[j - 1] + cost;
            if ins < best {
                best = ins;
            }
            if sub < best {
                best = sub;
            }
            curr.push(best);
        }
        prev = curr;
    }
    return prev[m];
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        return Stack { items: [x] + self.items }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            return self
        }
        return Stack { items: self.items[1..] }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            return None
        }
        return self.items[0]
    }
}

fn count_char(text: String, c: Char) -> Int {
    let mut count = 0
    for ch in text {
        if ch == c {
            count = count + 1
        }
    }
    return count
}

fn median(xs: [Float]) -> Float {
    let n = xs.len()

    // Insertion sort into a new list
    let mut sorted: [Float] = []
    for x in xs {
        let mut out: [Float] = []
        let mut placed = false
        for y in sorted {
            if !placed && x < y {
                out.push(x)
                placed = true
            }
            out.push(y)
        }
        if !placed {
            out.push(x)
        }
        sorted = out
    }

    let mid = n / 2
    if n % 2 == 1 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int] {
    let mut row: [Int] = [1]
    for i in 1..=n {
        let mut next: [Int] = []
        next.push(1)
        for j in 1..i {
            next.push(row[j - 1] + row[j])
        }
        next.push(1)
        row = next
    }
    return row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Insertion sort by start value
    let mut sorted: [(Int, Int)] = [];
    for iv in xs {
        let mut out: [(Int, Int)] = [];
        let mut placed = false;
        for s in sorted {
            if !placed && iv.0 < s.0 {
                out.push(iv);
                placed = true;
            }
            out.push(s);
        }
        if !placed {
            out.push(iv);
        }
        sorted = out;
    }

    // Merge overlapping or touching intervals
    let mut result: [(Int, Int)] = [];
    for iv in sorted {
        let n = result.len();
        if n > 0 && iv.0 <= result[n - 1].1 {
            let last = result[n - 1];
            let hi = if last.1 > iv.1 { last.1 } else { iv.1 };
            result[n - 1] = (last.0, hi);
        } else {
            result.push(iv);
        }
    }

    return result;
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let n = len(xs);
    if n == 0 {
        return fallback;
    }
    return xs[n - 1];
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let mut result: [(T, T)] = [];
    let n = xs.len();
    let mut i = 0;
    while i + 1 < n {
        result.push((xs[i], xs[i + 1]));
        i += 1;
    }
    result
}

fn names(xs: [Named]) -> String {
    let mut result = ""
    let mut first = true
    for x in xs {
        if first {
            result = x.name()
            first = false
        } else {
            result = result + ", " + x.name()
        }
    }
    result
}

fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
{
    return part * 100 / whole
}

fn message(e: LoginError) -> String {
    match e {
        NoSuchUser(name) => "no user {name}",
        WrongPassword => "wrong password",
        Locked(minutes) => "locked for {minutes} minutes",
    }
}

fn port_sum(text: String) -> Int ! PortError {
    parts = text.split(":")
    match parts {
        [a, b] => {
            left = try parse_port(a)
            right = try parse_port(b)
            left + right
        }
        _ => fail PortError.Bad(text: text)
    }
}

fn city(u: User) -> String {
    return u.address?.city?.upper() ?: "UNKNOWN"
}

fn sum_squares(from: Int, to: Int) -> Int ! Error {
  let mut total = 0
  let mut i = from
  while i <= to {
    total = total + i * i
    i = i + 1
  }
  return total
}

fn squares(n: Int) -> Int ! Error {
  let mid = n / 2
  let first = spawn sum_squares(1, mid)
  let second = spawn sum_squares(mid + 1, n)
  return await first + await second
}

fn total_qty(text: String) -> Int {
    match json.decode<List<Item>>(text) {
        Ok(items) => {
            var total = 0
            for item in items {
                total = total + item.qty
            }
            return total
        }
        Err(_) => return -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let mut sum: Decimal = Decimal::zero();
    for (price, qty) in items {
        let line: Decimal = price * Decimal::from_int(qty);
        sum = sum + line;
    }
    return sum;
}

fn deposit(a: Account, amount: Int) -> Account {
    a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    let n = xs.len()
    if n < 2 {
        return
    }
    let first = xs[0]
    xs[0] = xs[n - 1]
    xs[n - 1] = first
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    var result: [String] = []
    for (k, v) in m {
        if v >= min {
            result.append(k)
        }
    }
    result.sort()
    return result
}

fn numbered(items: [String]) -> String {
    let mut lines: [String] = [];
    let mut i = 1;
    for item in items {
        lines.push(i.to_string() + ". " + item);
        i = i + 1;
    }
    return lines.join("\n");
}

fn add_or_none(a: Int, b: Int) -> Int? {
    if b > 0 && a > Int.MAX - b {
        return none
    }
    if b < 0 && a < Int.MIN - b {
        return none
    }
    return a + b
}

fn adder(step: Int) -> fn(Int) -> Int {
    return |x: Int| -> Int { x + step };
}

fn key_count(events: [Event]) -> Int {
    let mut count = 0
    for e in events {
        match e {
            Key(_) => count = count + 1,
            _ => count = count
        }
    }
    count
}

fn csv(n: Int) -> String {
    let mut text = ""
    let mut i = 1
    while i <= n {
        if i > 1 {
            text = text + ","
        }
        text = text + i.to_string()
        i = i + 1
    }
    return text
}

fn strip_vowels(text: String) -> String {
    let mut result = String::new();
    for c in text.chars() {
        match c {
            'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U' => {}
            _ => result.push(c),
        }
    }
    result
}

fn is_power_of_two(n: Int) -> Bool {
    if n <= 0 {
        return false
    }
    let m = n
    while m % 2 == 0 {
        m = m / 2
    }
    return m == 1
}

fn binary(n: Int) -> String {
    if n == 0 {
        return "0"
    }
    let mut digits = ""
    let mut m = n
    while m > 0 {
        if m % 2 == 1 {
            digits = "1" + digits
        } else {
            digits = "0" + digits
        }
        m = m / 2
    }
    return digits
}

fn mode(xs: [Int]) -> Int {
    let mut best = xs[0];
    let mut best_count = 0;
    for x in xs {
        let mut count = 0;
        for y in xs {
            if y == x {
                count = count + 1;
            }
        }
        if count > best_count || (count == best_count && x < best) {
            best = x;
            best_count = count;
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let mut result: [String: Int] = {}
    let n = min(len(keys), len(values))
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    return result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 || b <= 0 || c <= 0 {
        return "invalid"
    }
    if a >= b + c || b >= a + c || c >= a + b {
        return "invalid"
    }
    if a == b && b == c {
        return "equilateral"
    }
    if a == b || b == c || a == c {
        return "isosceles"
    }
    return "scalene"
}

// Note: I'm not certain of Kavach's exact standard library names,
// so this assumes Rust-like string and list methods.
fn lengths(text: String) -> [Int] {
    if text.len() == 0 {
        return []
    }
    return text.split(" ").map(|w| w.len()).collect()
}

fn collatz(n: Int) -> Int {
    let mut x = n;
    let mut steps = 0;
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2;
        } else {
            x = 3 * x + 1;
        }
        steps = steps + 1;
    }
    return steps;
}

fn sum_digits(text: String) -> Int {
    let mut total: Int = 0;
    for c in text.chars() {
        if c >= '0' && c <= '9' {
            total = total + (c as Int) - ('0' as Int);
        }
    }
    return total;
}

fn top(players: [Player], k: Int) -> [String] {
    let mut sorted: [Player] = []
    for p in players {
        // Walk left past players with lower scores so equal scores keep their original order.
        let mut i = sorted.len()
        while i > 0 && sorted[i - 1].score < p.score {
            i = i - 1
        }
        sorted.insert(i, p)
    }

    let mut names: [String] = []
    let mut j = 0
    while j < k && j < sorted.len() {
        names.push(sorted[j].name)
        j = j + 1
    }
    return names
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int] {
    let mut result: [Int] = []
    for x in xs {
        let v = if x < lo { lo } else if x > hi { hi } else { x }
        result.push(v)
    }
    return result
}

fn is_sorted(xs: [Int]) -> Bool {
    let n = len(xs)
    let mut i = 1
    while i < n {
        if xs[i - 1] > xs[i] {
            return false
        }
        i = i + 1
    }
    return true
}

fn hex_digit(d: Int) -> String {
    if d == 0 { return "0" }
    if d == 1 { return "1" }
    if d == 2 { return "2" }
    if d == 3 { return "3" }
    if d == 4 { return "4" }
    if d == 5 { return "5" }
    if d == 6 { return "6" }
    if d == 7 { return "7" }
    if d == 8 { return "8" }
    if d == 9 { return "9" }
    if d == 10 { return "a" }
    if d == 11 { return "b" }
    if d == 12 { return "c" }
    if d == 13 { return "d" }
    if d == 14 { return "e" }
    return "f"
}

fn hex_byte(n: Int) -> String {
    let hi = n / 16
    let lo = n % 16
    return hex_digit(hi) + hex_digit(lo)
}

fn hex(r: Int, g: Int, b: Int) -> String {
    return "#" + hex_byte(r) + hex_byte(g) + hex_byte(b)
}

fn simulate(commands: [Int]) -> [Int] {
    let mut queue: [Int] = []
    for cmd in commands {
        if cmd > 0 {
            queue.push(cmd)
        } else if cmd == 0 && queue.len() > 0 {
            queue.remove(0)
        }
    }
    return queue
}

fn sum_evens(xs: [Int]) -> Int {
    let total = 0
    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    const words = text.split(" ")
    let reversed: [String] = []
    const n = words.len()
    for i in 0..n {
        reversed.push(words[n - 1 - i])
    }
    reversed.join(" ")
}

fn is_palindrome(text: String) -> Bool {
    const letters = text.lower().chars()
    const n = letters.len()
    let same = true
    for i in 0..(n / 2) {
        if letters[i] != letters[n - 1 - i] {
            same = false
            break
        }
    }
    same
}

fn count_vowels(text: String) -> Int {
    let total = 0
    for c in text.chars() {
        if c == "a" or c == "e" or c == "i" or c == "o" or c == "u" or
            c == "A" or c == "E" or c == "I" or c == "O" or c == "U" {
            total += 1
        }
    }
    total
}

pub fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        "FizzBuzz"
    } else if n % 3 == 0 {
        "Fizz"
    } else if n % 5 == 0 {
        "Buzz"
    } else {
        String(n)
    }
}

fn largest(xs: [Int]) -> Int? {
    let best: Int? = none
    for x in xs {
        if best == none or x > (best ?? x) {
            best = x
        }
    }
    best
}

fn word_counts(text: String) -> [String: Int] {
    let counts: [String: Int] = [:]
    for word in text.split(" ") {
        counts[word] = (counts[word] ?? 0) + 1
    }
    counts
}

fn doubled(text: String) -> Int ! BadInput {
    match Int(text) {
        ok(n) => n * 2
        err(_) => fail BadInput.NotANumber(text: text)
    }
}

fn factorial(n: Int) -> Int {
    let result = 1
    let i = 2
    while i <= n {
        result = result * i
        i += 1
    }
    result
}

fn fib(n: Int) -> Int
    require n >= 0
{
    let a = 0
    let b = 1
    for _ in 0..n {
        const next = a + b
        a = b
        b = next
    }
    a
}

fn by_length(words: [String]) -> [String] {
    let longest = 0
    for word in words {
        if word.len() > longest {
            longest = word.len()
        }
    }
    let result: [String] = []
    for n in 0..(longest + 1) {
        for word in words {
            if word.len() == n {
                result.push(word)
            }
        }
    }
    result
}

fn dedupe(xs: [Int]) -> [Int] {
    let result: [Int] = []
    for x in xs {
        if not result.contains(x) {
            result.push(x)
        }
    }
    result
}

fn total_area(rects: [Rect]) -> Float {
    let total = 0.0
    for rect in rects {
        total += rect.width * rect.height
    }
    total
}

fn area(s: Shape) -> Float {
    match s {
        Shape.Circle(radius) => 3.14 * radius * radius
        Shape.Square(side) => side * side
    }
}

fn first_negative(xs: [Int]) -> Int? {
    let result: Int? = none
    for i in 0..xs.len() {
        if xs[i] < 0 {
            result = i
            break
        }
    }
    result
}

fn caesar(text: String, k: Int) -> String {
    const alphabet = "abcdefghijklmnopqrstuvwxyz".chars()
    let out = ""
    for c in text.chars() {
        let shifted = c
        for i in 0..26 {
            if alphabet[i] == c {
                shifted = alphabet[(i + k) % 26]
            }
        }
        out += shifted
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let result: [[Int]] = []
    for j in 0..m[0].len() {
        let column: [Int] = []
        for row in m {
            column.push(row[j])
        }
        result.push(column)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    let result: Int? = none
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            result = mid
            break
        }
        if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    result
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail MathError.DivideByZero
    }
    a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let groups: [String: [String]] = [:]
    for word in words {
        const letter = word.slice(0, 1)
        let group = groups[letter] ?? []
        group.push(word)
        groups[letter] = group
    }
    groups
}

fn running(xs: [Int]) -> [Int] {
    let out: [Int] = []
    let total = 0
    for x in xs {
        total += x
        out.push(total)
    }
    out
}

fn gcd(a: Int, b: Int) -> Int
    require a > 0
    require b > 0
{
    let x = a
    let y = b
    while y != 0 {
        const r = x % y
        x = y
        y = r
    }
    x
}

fn title(text: String) -> String {
    const words = text.split(" ")
    let out: [String] = []
    for word in words {
        const first = word.slice(0, 1).upper()
        const rest = word.slice(1, word.len()).lower()
        out.push(first + rest)
    }
    out.join(" ")
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else {
        let i = 2
        let prime = true
        while prime and i * i <= n {
            if n % i == 0 {
                prime = false
            }
            i += 1
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let result: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        let d = 2
        while d * d <= candidate {
            if candidate % d == 0 {
                is_prime = false
                break
            }
            d += 1
        }
        if is_prime {
            result.push(candidate)
        }
        candidate += 1
    }
    result
}

fn digit_sum(n: Int) -> Int
    require n >= 0
{
    let total = 0
    let rest = n
    while rest > 0 {
        total += rest % 10
        rest = rest / 10
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    for ch in text.chars() {
        if count > 0 and ch == current {
            count += 1
        } else {
            if count > 0 {
                result += "{current}{count}"
            }
            current = ch
            count = 1
        }
    }
    if count > 0 {
        result += "{current}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        if c == "(" or c == "[" or c == "{" {
            stack.push(c)
        } else if c == ")" or c == "]" or c == "}" {
            const want = match c {
                ")" => "("
                "]" => "["
                _ => "{"
            }
            if let top = stack.pop() {
                if top != want {
                    ok = false
                }
            } else {
                ok = false
            }
        }
    }
    ok and stack.len() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let found: (Int, Int)? = none
    outer: for i in 0..xs.len() {
        for j in (i + 1)..xs.len() {
            if xs[i] + xs[j] == target {
                found = (i, j)
                break outer
            }
        }
    }
    found
}

fn anagrams(a: String, b: String) -> Bool {
    const left = a.lower().chars().sort()
    const right = b.lower().chars().sort()
    left == right
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const table: [(Int, String)] = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    let remaining = n
    let result = ""
    for (value, symbol) in table {
        while remaining >= value {
            result = result + symbol
            remaining -= value
        }
    }
    result
}

fn flatten(xss: [[Int]]) -> [Int] {
    let out: [Int] = []
    for xs in xss {
        out += xs
    }
    out
}

pub fn chunks(xs: [Int], n: Int) -> [[Int]]
    require n >= 1
{
    let result: [[Int]] = []
    let rest = xs
    while rest.len() > 0 {
        result.push(rest.take(n))
        rest = rest.skip(n)
    }
    result
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    const n = xs.len()
    const s = if n == 0 { 0 } else { k % n }
    xs.skip(s) + xs.take(s)
}

fn common_prefix(words: [String]) -> String {
    if words.len() == 0 {
        ""
    } else {
        let prefix = words[0]
        for word in words.skip(1) {
            let n = 0
            while n < prefix.len and n < word.len and prefix.slice(n, n + 1) == word.slice(n, n + 1) {
                n += 1
            }
            prefix = prefix.slice(0, n)
        }
        prefix
    }
}

fn second_largest(xs: [Int]) -> Int? {
    let distinct: [Int] = []
    for x in xs {
        if not distinct.contains(x) {
            distinct.push(x)
        }
    }
    distinct.sort()
    if distinct.len() < 2 {
        none
    } else {
        distinct[distinct.len() - 2]
    }
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    let prev: [Int] = []
    for j in 0..ys.len() + 1 {
        prev.push(j)
    }
    for i in 0..xs.len() {
        let cur: [Int] = [i + 1]
        for j in 0..ys.len() {
            const cost = if xs[i] == ys[j] { 0 } else { 1 }
            const deletion = prev[j + 1] + 1
            const insertion = cur[j] + 1
            const substitution = prev[j] + cost
            const best = if deletion < insertion { deletion } else { insertion }
            cur.push(if substitution < best { substitution } else { best })
        }
        prev = cur
    }
    prev[ys.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        self with { items: [x] + self.items }
    }

    fn pop(self) -> Stack {
        self with { items: self.items.skip(1) }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 { none } else { self.items[0] }
    }
}

fn count_char(text: String, c: Char) -> Int {
    let count = 0
    for ch in text.chars() {
        if ch == c {
            count += 1
        }
    }
    count
}

fn median(xs: [Float]) -> Float
    require xs.len() > 0
{
    const sorted = xs.sort()
    const n = xs.len()
    const mid = n / 2
    if n % 2 == 1 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int] {
    let row = [1]
    for _ in 0..n {
        let next: [Int] = []
        let prev = 0
        for x in row {
            next.push(prev + x)
            prev = x
        }
        next.push(prev)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let merged: [(Int, Int)] = []
    let has_current = false
    let cur_lo = 0
    let cur_hi = 0
    for (lo, hi) in sorted {
        if not has_current {
            cur_lo = lo
            cur_hi = hi
            has_current = true
        } else if lo <= cur_hi {
            if hi > cur_hi {
                cur_hi = hi
            }
        } else {
            merged.push((cur_lo, cur_hi))
            cur_lo = lo
            cur_hi = hi
        }
    }
    if has_current {
        merged.push((cur_lo, cur_hi))
    }
    merged
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let result = fallback
    let rest = xs
    if let last = rest.pop() {
        result = last
    }
    result
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let out: [(T, T)] = []
    let prev: T? = none
    for x in xs {
        if let p = prev {
            out.push((p, x))
        }
        prev = x
    }
    out
}

fn names(xs: [Named]) -> String {
    let parts: [String] = []
    for x in xs {
        parts.push(x.name())
    }
    parts.join(", ")
}

fn message(e: LoginError) -> String {
    match e {
        LoginError.NoSuchUser(name) => "no user {name}"
        LoginError.WrongPassword => "wrong password"
        LoginError.Locked(minutes) => "locked for {minutes} minutes"
    }
}

fn port_sum(text: String) -> Int ! PortError {
    const parts = text.split(":")
    if parts.len() != 2 {
        fail PortError.Bad(text: text)
    }
    const a = try parse_port(parts[0])
    const b = try parse_port(parts[1])
    a + b
}

fn city(u: User) -> String {
    (u.address?.city ?? "UNKNOWN").upper()
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    let first = 0
    for i in 1..mid + 1 {
        first += i * i
    }
    let second = 0
    for i in (mid + 1)..(n + 1) {
        second += i * i
    }
    first + second
}

fn total_qty(text: String) -> Int {
    match json.decode<[Item]>(text) {
        ok(items) => items.sum(.qty)
        err(_) => -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let sum: Decimal = 0.00
    for (price, quantity) in items {
        for _ in 0..quantity {
            sum += price
        }
    }
    sum
}

fn deposit(a: Account, amount: Int) -> Account {
    a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    if xs.len() >= 2 {
        const last = xs.len() - 1
        const first = xs[0]
        xs[0] = xs[last]
        xs[last] = first
    }
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let keys: [String] = []
    for (key, value) in m {
        if value >= min {
            keys.push(key)
        }
    }
    keys.sort()
}

fn numbered(items: [String]) -> String {
    let lines: [String] = []
    let n = 0
    for item in items {
        n += 1
        lines.push("{n}. {item}")
    }
    lines.join("\n")
}

fn add_or_none(a: Int, b: Int) -> Int? {
    // Int.max and Int.min are assumed to be the built-in integer bounds.
    if b > 0 and a > Int.max - b {
        none
    } else if b < 0 and a < Int.min - b {
        none
    } else {
        a + b
    }
}

fn adder(step: Int) -> fn(Int) -> Int {
    x => x + step
}

fn key_count(events: [Event]) -> Int {
    events.count(e => match e {
        Event.Key(_) => true
        _ => false
    })
}

fn csv(n: Int) -> String {
    let text = ""
    const end = n + 1
    for i in 1..end {
        if i > 1 {
            text += ","
        }
        text += "{i}"
    }
    text
}

fn strip_vowels(text: String) -> String {
    const vowels = ["a", "e", "i", "o", "u", "A", "E", "I", "O", "U"]
    text.chars().filter(c => not vowels.contains(c)).join("")
}

fn is_power_of_two(n: Int) -> Bool {
    if n < 1 {
        false
    } else {
        let rest = n
        while rest % 2 == 0 {
            rest = rest / 2
        }
        rest == 1
    }
}

fn binary(n: Int) -> String {
    if n == 0 {
        "0"
    } else {
        let rest = n
        let text = ""
        while rest > 0 {
            text = "{rest % 2}{text}"
            rest = rest / 2
        }
        text
    }
}

fn mode(xs: [Int]) -> Int
    require xs.len() > 0
{
    const sorted = xs.sort()
    let best = sorted[0]
    let best_count = 0
    let current = sorted[0]
    let run = 0
    for x in sorted {
        if x == current {
            run += 1
        } else {
            current = x
            run = 1
        }
        if run > best_count {
            best = current
            best_count = run
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    const n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 or a >= b + c or b >= a + c or c >= a + b {
        "invalid"
    } else if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn lengths(text: String) -> [Int] {
    let result: [Int] = []
    for word in text.split(" ") {
        result.push(word.len())
    }
    result
}

fn collatz(n: Int) -> Int {
    let value = n
    let steps = 0
    while value != 1 {
        if value % 2 == 0 {
            value = value / 2
        } else {
            value = 3 * value + 1
        }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int {
    let total = 0
    for c in text.chars() {
        const d = Int(c) catch -1
        if d >= 0 {
            total += d
        }
    }
    total
}

pub fn top(players: [Player], k: Int) -> [String] {
    let remaining = players
    let names: [String] = []
    while names.len() < k and remaining.len() > 0 {
        let best = 0
        for i in 1..remaining.len() {
            if remaining[i].score > remaining[best].score {
                best = i
            }
        }
        names.push(remaining[best].name)
        remaining = remaining.take(best) + remaining.skip(best + 1)
    }
    names
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    require lo <= hi
{
    let out: [Int] = []
    for x in xs {
        const clamped = if x < lo { lo } else { if x > hi { hi } else { x } }
        out.push(clamped)
    }
    out
}

fn is_sorted(xs: [Int]) -> Bool {
    let ok = true
    for i in 0..(xs.len() - 1) {
        if xs[i] > xs[i + 1] {
            ok = false
        }
    }
    ok
}

fn hex_digit(n: Int) -> String {
    "0123456789abcdef".slice(n, n + 1)
}

fn hex_byte(v: Int) -> String {
    hex_digit(v / 16) + hex_digit(v % 16)
}

fn hex(r: Int, g: Int, b: Int) -> String {
    "#" + hex_byte(r) + hex_byte(g) + hex_byte(b)
}

fn simulate(commands: [Int]) -> [Int] {
    let queue: [Int] = []
    for command in commands {
        if command > 0 {
            queue.push(command)
        } else if command == 0 and queue.len() > 0 {
            queue = queue.skip(1)
        }
    }
    queue
}

fn sum_evens(xs: [Int]) -> Int {
