    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    const words = text.split(" ")
    let reversed: [String] = []
    for i in 0..words.len() {
        reversed.push(words[words.len() - 1 - i])
    }
