fn is_palindrome(text: String) -> Bool {
    const cs = text.lower().chars()
    let i = 0
    let j = cs.len() - 1
    let same = true
    while same and i < j {
        if cs[i] != cs[j] {
            same = false
        } else {
            i += 1
            j -= 1
        }
    }
    same
}

fn count_vowels(text: String) -> Int {
    const vowels = ["a", "e", "i", "o", "u", "A", "E", "I", "O", "U"]
    let count = 0
    for c in text.chars() {
        const letter = "{c}"
        if vowels.contains(letter) {
            count += 1
        }
    }
    count
}

