fn caesar(text: String, k: Int) -> String {
    const alphabet = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"]
    let result = ""
    for ch in text.chars() {
        const c = String(ch)
        let shifted = c
        for i in 0..26 {
            if c == alphabet[i] {
                shifted = alphabet[(i + k) % 26]
            }
        }
        result += shifted
    }
    result
}

fn transpose(m: [[Int]]) -> [[Int]] {
