    const cols = m[0].len()
    let out: [[Int]] = []
    for c in 0..cols {
        let column: [Int] = []
        for r in 0..rows {
            column.push(m[r][c])
        }
        out.push(column)
    }
    out
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    let found: Int? = none
    while lo < hi and found == none {
        let mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            found = mid
        } else if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    found
}

