fn rle(text: String) -> String {
    let out = ""
    let current = ""
    let count = 0
    for ch in text.chars() {
        const c = String(ch)
        if count > 0 and c == current {
            count += 1
        } else {
            if count > 0 {
                out = out + current + String(count)
            }
            current = c
            count = 1
        }
    }
    if count > 0 {
        out = out + current + String(count)
    }
    out
}

fn balanced(text: String) -> Bool {
    let stack: [Char] = []
    let ok = true
    for c in text.chars() {
        if not ok {
            break
        }
        if c == '(' or c == '[' or c == '{' {
            stack.push(c)
        } else if c == ')' or c == ']' or c == '}' {
            let expected = if c == ')' { '(' } else if c == ']' { '[' } else { '{' }
            if let open = stack.pop() {
                if open != expected {
                    ok = false
                }
            } else {
                ok = false
            }
        }
    }
    ok and stack.len() == 0
}

