            }
            if x > b {
                second = best
                best = x
            } else if let s = second {
                if x > s {
                    second = x
                }
            } else {
                second = x
            }
        } else {
            best = x
        }
    }
    second
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    let prev = [0]
    for j in 1..ys.len() + 1 {
        prev.push(j)
    }
    for i in 0..xs.len() {
        let curr = [i + 1]
        for j in 0..ys.len() {
            const sub_cost = if xs[i] == ys[j] { 0 } else { 1 }
            const del_cost = prev[j + 1] + 1
            const ins_cost = curr[j] + 1
            const rep_cost = prev[j] + sub_cost
            let best = if del_cost < ins_cost { del_cost } else { ins_cost }
            if rep_cost < best {
                best = rep_cost
            }
            curr.push(best)
        }
        prev = curr
    }
    prev[ys.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        self with { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            self with { items: self.items.take(self.items.len() - 1) }
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

