}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort()
    let merged: [(Int, Int)] = []
    for (start, end) in sorted {
        if let last = merged.pop() {
            const (last_start, last_end) = last
            if start <= last_end {
                const top = if end > last_end { end } else { last_end }
                merged.push((last_start, top))
            } else {
                merged.push(last)
                merged.push((start, end))
            }
        } else {
            merged.push((start, end))
        }
    }
    merged
}

