fn top(players: [Player], k: Int) -> [String] {
    let remaining = players
    let names: [String] = []
    let taken = 0
    while taken < k and remaining.len() > 0 {
        // Pick the first player with the highest score; strict > keeps ties in order.
        let best = 0
        let j = 1
        while j < remaining.len() {
            if remaining[j].score > remaining[best].score {
                best = j
            }
            j += 1
        }
        names.push(remaining[best].name)
        remaining = remaining.take(best) + remaining.skip(best + 1)
        taken += 1
    }
    names
}

