    let total = 0
    for x in xs {
        total += x
        out += [total]
    }
    out
}

fn title(text: String) -> String {
    const words = text.split(" ")
    const parts = words.map(w => capitalize(w))
    parts.join(" ")
}

fn capitalize(word: String) -> String {
    const first = word.slice(0, 1)
    const rest = word.slice(1, word.len())
    first.upper() + rest.lower()
}

fn is_prime(n: Int) -> Bool
    require n <= 1_000_000_000_000
    example is_prime(7) == true
    example is_prime(9) == false
{
    if n < 2 {
        false
    } else {
        let d = 2
        let prime = true
        while d * d <= n and prime {
            if n % d == 0 {
                prime = false
            }
            d += 1
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let found: [Int] = []
    for k in 2..n {
        let divisor = 2
        let prime = true
        while prime and divisor * divisor <= k {
            if k % divisor == 0 {
                prime = false
            }
            divisor += 1
        }
        if prime {
            found.push(k)
        }
    }
    found
}

fn digit_sum(n: Int) -> Int {
    let total = 0
    let rest = n
    while rest > 0 {
        total += rest % 10
        rest = rest / 10
    }
    total
}

fn rle(text: String) -> String {
    let out = ""
    let current = ""
    let count = 0
    for c in text.chars() {
        const s = String(c)
        if count > 0 and s == current {
            count += 1
        } else {
            if count > 0 {
                out += current + String(count)
            }
            current = s
            count = 1
        }
    }
    if count > 0 {
        out += current + String(count)
    }
    out
}

fn opener_of(close: String) -> String {
    if close == ")" {
        "("
    } else if close == "]" {
        "["
    } else {
        "\{"
    }
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        const ch = String(c)
        if ch == "(" or ch == "[" or ch == "\{" {
            stack.push(ch)
        } else if ch == ")" or ch == "]" or ch == "}" {
            const top = stack.pop() ?? ""
            if top != opener_of(ch) {
                ok = false
            }
        }
    }
    ok and stack.len() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let found: (Int, Int)? = none
    outer: for i in 0..xs.len() {
        const start = i + 1
        for j in start..xs.len() {
            if xs[i] + xs[j] == target {
                found = (i, j)
                break outer
            }
        }
    }
    found
}

fn anagrams(a: String, b: String) -> Bool {
    const left = a.lower().chars().sort()
    const right = b.lower().chars().sort()
    left == right
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    const symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    let rest = n
    let out = ""
    for i in 0..values.len() {
        while rest >= values[i] {
            out += symbols[i]
            rest -= values[i]
        }
    }
    out
}

fn flatten(xss: [[Int]]) -> [Int] {
    let out: [Int] = []
    for xs in xss {
        out += xs
    }
    out
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let out: [[Int]] = []
    let cur: [Int] = []
    for x in xs {
        cur.push(x)
        if cur.len() == n {
            out.push(cur)
            cur = []
        }
    }
    if cur.len() > 0 {
        out.push(cur)
    }
    out
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    const n = xs.len()
    const r = if n == 0 { 0 } else { k % n }
    xs.skip(r) + xs.take(r)
}

fn common_prefix(words: [String]) -> String {
    if words.len() == 0 {
        ""
    } else {
        const first = words[0].chars()
        let n = first.len()
        for word in words {
            const other = word.chars()
            let i = 0
            while i < n and i < other.len() and first[i] == other[i] {
                i += 1
            }
            n = i
        }
        first.take(n).join("")
    }
}

fn second_largest(xs: [Int]) -> Int? {
    let top: Int? = none
    let second: Int? = none
    for x in xs {
        if let t = top {
            if x > t {
                second = top
                top = x
            } else if x < t {
                if let s = second {
                    if x > s {
                        second = x
                    }
                } else {
                    second = x
                }
            }
        } else {
            top = x
        }
    }
    second
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const x = a.chars()
    const y = b.chars()
    let prev: [Int] = []
    for j in 0..(y.len() + 1) {
        prev.push(j)
    }
    for i in 0..x.len() {
        let curr: [Int] = [i + 1]
        for j in 0..y.len() {
            const cost = if x[i] == y[j] { 0 } else { 1 }
            const del = prev[j + 1] + 1
            const ins = curr[j] + 1
            const sub = prev[j] + cost
            const low = if del < ins { del } else { ins }
            curr.push(if low < sub { low } else { sub })
        }
        prev = curr
    }
    prev[y.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            Stack(items: self.items.take(self.items.len() - 1))
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

fn count_char(text: String, c: Char) -> Int {
    text.chars().count(ch => ch == c)
}

fn median(xs: [Float]) -> Float {
    const sorted = xs.sort()
    const n = xs.len()
    const mid = n / 2
    if n % 2 != 0 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int] {
    let row = [1]
    for _ in 0..n {
        let next = [1]
        for i in 0..row.len() - 1 {
            next.push(row[i] + row[i + 1])
        }
        next.push(1)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by((p) => p.0)
    let out: [(Int, Int)] = []
    let has_cur = false
    let cur_s = 0
    let cur_e = 0
    for (s, e) in sorted {
        if not has_cur {
            cur_s = s
            cur_e = e
            has_cur = true
        } else if s <= cur_e {
            if e > cur_e {
                cur_e = e
            }
        } else {
            out.push((cur_s, cur_e))
            cur_s = s
            cur_e = e
        }
    }
    if has_cur {
        out.push((cur_s, cur_e))
    }
    out
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    if xs.len() == 0 {
        fallback
    } else {
        xs[xs.len() - 1]
    }
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let result: [(T, T)] = []
    for i in 0..xs.len() - 1 {
        result.push((xs[i], xs[i + 1]))
    }
    result
}

