fn swap_ends(inout xs: [Int]) {
    if xs.len() >= 2 {
        const last = xs[xs.len() - 1]
        xs[xs.len() - 1] = xs[0]
        xs[0] = last
    }
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let keys: [String] = []
    for (key, value) in m {
        if value >= min {
            keys.push(key)
        }
    }
    const sorted = keys.sort()
    sorted
}

fn numbered(items: [String]) -> String {
    let lines: [String] = []
    for i in 0..items.len() {
        lines.push("{i + 1}. {items[i]}")
    }
    lines.join("\n")
