fn add_or_none(a: Int, b: Int) -> Int? {
    const max_int = 9_223_372_036_854_775_807
    const min_int = -9_223_372_036_854_775_807 - 1
    if b > 0 and a > max_int - b {
        none
    } else if b < 0 and a < min_int - b {
        none
    } else {
        a + b
    }
}

fn adder(step: Int) -> fn(Int) -> Int {
