fn is_power_of_two(n: Int) -> Bool {
    if n < 1 {
        false
    } else {
        let m = n
        while m % 2 == 0 {
            m = m / 2
        }
        m == 1
    }
}

fn binary(n: Int) -> String {
    if n == 0 {
        "0"
    } else {
        let m = n
        let digits = ""
        while m > 0 {
            digits = "{m % 2}{digits}"
            m = m / 2
        }
        digits
    }
}

fn mode(xs: [Int]) -> Int {
    const sorted = xs.sort()
    let best = sorted[0]
    let best_count = 0
    let i = 0
    while i < sorted.len() {
        let j = i
        while j < sorted.len() and sorted[j] == sorted[i] {
            j += 1
        }
        const run = j - i
        if run > best_count {
            best = sorted[i]
            best_count = run
        }
        i = j
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    let n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 or a >= b + c or b >= a + c or c >= a + b {
        "invalid"
    } else if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn lengths(text: String) -> [Int] {
