}

fn collatz(n: Int) -> Int
    require n >= 1
{
    let x = n
    let steps = 0
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = 3 * x + 1
        }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int {
    let total = 0
    for c in text.chars() {
        if c >= '0' and c <= '9' {
            total += Int(String(c)) catch 0
        }
    }
    total
}

fn top(players: [Player], k: Int) -> [String] {
    let names: [String] = []
    let n = players.len()
    let limit = if k < n { k } else { n }
    for r in 0..limit {
        for i in 0..n {
            let rank = 0
            for j in 0..n {
                if players[j].score > players[i].score or (players[j].score == players[i].score and j < i) {
                    rank += 1
                }
            }
            if rank == r {
                names.push(players[i].name)
            }
        }
    }
    names
}

pub fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    example clamp_all([1, 5, 10, -3], 0, 8) == [1, 5, 8, 0]
{
    let out: [Int] = []
    for x in xs {
        const v = if x < lo { lo } else { if x > hi { hi } else { x } }
        out += [v]
    }
    out
}

fn is_sorted(xs: [Int]) -> Bool {
    let ok = true
    let i = 1
    while i < xs.len() {
        if xs[i - 1] > xs[i] {
            ok = false
            break
        }
        i += 1
    }
    ok
}

fn hex_digit(n: Int) -> String {
