}

fn byte_hex(n: Int) -> String {
    hex_digit(n / 16) + hex_digit(n % 16)
}

fn hex(r: Int, g: Int, b: Int) -> String {
    "#" + byte_hex(r) + byte_hex(g) + byte_hex(b)
}

fn simulate(commands: [Int]) -> [Int] {
    let queue: [Int] = []
    for c in commands {
        if c > 0 {
            queue.push(c)
        } else if c == 0 and queue.len() > 0 {
            queue = queue.skip(1)
        }
    }
    queue
}

