fn is_palindrome(text: String) -> Bool {
    let s = text.to_lowercase();
    let mut i = 0;
    let mut j = s.len() - 1;

    if s.len() == 0 {
        return true;
    }

    while i < j {
        if s.char_at(i) != s.char_at(j) {
            return false;
        }
        i = i + 1;
        j = j - 1;
    }

    return true;
}

