    match parse_int(text) {
        Some(n) => n * 2,
        None => fail NotANumber(text: text),
    }
}

fn factorial(n: Int) -> Int {
    if n <= 1 {
        return 1;
    }
    return n * factorial(n - 1);
}

fn fib(n: Int) -> Int {
    let mut a = 0;
    let mut b = 1;
    let mut i = 0;
    while i < n {
        let t = a + b;
        a = b;
        b = t;
        i = i + 1;
    }
    return a;
}

fn by_length(words: [String]) -> [String] {
    let mut max_len: Int = 0;
    for w in words {
        if len(w) > max_len {
            max_len = len(w);
        }
    }

    let mut result: [String] = [];
    for l in 0..=max_len {
        for w in words {
            if len(w) == l {
                push(result, w);
            }
        }
    }
    return result;
}

fn dedupe(xs: [Int]) -> [Int] {
    let mut result: [Int] = []
    for x in xs {
        let mut seen = false
        for y in result {
            if y == x {
                seen = true
            }
        }
        if !seen {
            result.push(x)
        }
    }
    return result
}

fn total_area(rects: [Rect]) -> Float {
    let mut total = 0.0
    for r in rects {
        total = total + r.width * r.height
    }
    return total
}

fn area(s: Shape) -> Float {
    match s {
