        Square(side) => side * side,
    }
}

fn first_negative(xs: [Int]) -> Int? {
    let mut i = 0;
    while i < len(xs) {
        if xs[i] < 0 {
            return some(i);
        }
        i = i + 1;
    }
    return none;
}

fn caesar(text: String, k: Int) -> String {
    let result: String = "";
    for ch in text {
        if ch >= 'a' && ch <= 'z' {
            let shifted: Int = (ord(ch) - ord('a') + k) % 26 + ord('a');
            result = result + chr(shifted);
        } else {
            result = result + ch;
        }
    }
    return result;
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let rows = len(m)
    let cols = len(m[0])
    let mut result: [[Int]] = []
    let mut j = 0
    while j < cols {
        let mut row: [Int] = []
        let mut i = 0
        while i < rows {
            row.push(m[i][j])
            i = i + 1
        }
        result.push(row)
        j = j + 1
    }
    return result
}

// Note: I don't know Kavach well, so the syntax below (len(), let mut, none, implicit Int -> Int? wrapping) is assumed.
fn find(xs: [Int], target: Int) -> Int? {
    let mut lo: Int = 0
    let mut hi: Int = xs.len()

    while lo < hi {
        let mid: Int = lo + (hi - lo) / 2
        let v: Int = xs[mid]

        if v == target {
            return mid
        } else if v < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }

    return none
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail DivideByZero
    }
    return a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let mut result: [String: [String]] = [:];
    for word in words {
        let key: String = word.first_char().to_string();
        if !result.contains_key(key) {
            result[key] = [];
        }
        result[key].push(word);
    }
    return result;
}

