fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        return a;
    }
    return gcd(b, a % b);
}

// Note: I'm not certain of Kavach's exact standard library, so this assumes
// Rust-like syntax and methods (chars, to_uppercase, to_lowercase, String concatenation).
fn title(text: String) -> String {
    let mut result: String = "";
    let mut at_word_start: Bool = true;

    for ch in text.chars() {
        if ch == ' ' {
            result = result + " ";
            at_word_start = true;
        } else if at_word_start {
            result = result + ch.to_uppercase();
            at_word_start = false;
        } else {
            result = result + ch.to_lowercase();
        }
    }

    return result;
}

// Note: I don't have reliable knowledge of Kavach's syntax, so this assumes a Rust-like style.
fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false;
    }
    if n < 4 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i = i + 2;
    }
    return true;
}

fn primes_below(n: Int) -> [Int] {
    let mut result: [Int] = [];
    if n <= 2 {
        return result;
    }

    let mut is_prime: [Bool] = [];
    let mut i: Int = 0;
    while i < n {
        is_prime.push(true);
        i = i + 1;
    }

    let mut p: Int = 2;
    while p < n {
        if is_prime[p] {
            result.push(p);
            let mut multiple: Int = p * p;
            while multiple < n {
                is_prime[multiple] = false;
                multiple = multiple + p;
            }
        }
        p = p + 1;
    }

    return result;
}

