// Note: I don't know Kavach's actual syntax. This assumes Rust-like syntax
// based on the given signature, so it may need adjusting.
fn rle(text: String) -> String {
    let mut out = String::new();
    let mut prev: Option<char> = None;
    let mut count = 0;

    for c in text.chars() {
        match prev {
            Some(p) if p == c => {
                count += 1;
            }
            Some(p) => {
                out.push(p);
                out.push_str(&count.to_string());
                prev = Some(c);
                count = 1;
            }
            None => {
                prev = Some(c);
                count = 1;
            }
        }
    }

    if let Some(p) = prev {
        out.push(p);
        out.push_str(&count.to_string());
    }

    out
}

// Note: I'm not certain of Kavach's exact standard library, so this assumes
// Rust-like syntax with a growable list type (push/pop/is_empty) and `text.chars()`.
fn balanced(text: String) -> Bool {
    let mut stack: List<Char> = [];

    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}' {
            if stack.is_empty() {
                return false;
            }

            let open = stack.pop();

            if (c == ')' && open != '(')
                || (c == ']' && open != '[')
                || (c == '}' && open != '{') {
                return false;
            }
        }
    }

    return stack.is_empty();
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
