        return "";
    }

    let mut prefix = words[0];

    for i in 1..words.len() {
        let word = words[i];
        let mut j = 0;

        while j < prefix.len() && j < word.len() && prefix[j] == word[j] {
            j = j + 1;
        }

        prefix = prefix.substring(0, j);

        if prefix.len() == 0 {
            return "";
        }
    }

    return prefix;
}

fn second_largest(xs: [Int]) -> Int? {
    var has_first = false
    var has_second = false
    var first = 0
    var second = 0

    for x in xs {
        if !has_first {
            first = x
            has_first = true
        } else if x > first {
            second = first
            has_second = true
            first = x
        } else if x < first && (!has_second || x > second) {
            second = x
            has_second = true
        }
    }

    if has_second {
        return second
    }
    return none
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let mut result: [Int] = [];
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i]);
            i = i + 1;
        } else {
            result.push(b[j]);
            j = j + 1;
        }
    }

    while i < a.len() {
        result.push(a[i]);
        i = i + 1;
    }

    while j < b.len() {
        result.push(b[j]);
        j = j + 1;
    }

    return result;
}

fn distance(a: String, b: String) -> Int {
    let n = a.len();
    let m = b.len();

    if n == 0 {
        return m;
    }
    if m == 0 {
        return n;
    }

    let mut prev = [];
    let mut j = 0;
    while j <= m {
        prev.push(j);
        j = j + 1;
    }

    let mut i = 1;
    while i <= n {
        let mut curr = [];
        curr.push(i);

        let mut j = 1;
        while j <= m {
            let cost = if a.char_at(i - 1) == b.char_at(j - 1) { 0 } else { 1 };

            let deletion = prev[j] + 1;
            let insertion = curr[j - 1] + 1;
            let substitution = prev[j - 1] + cost;

            let mut best = deletion;
            if insertion < best {
                best = insertion;
            }
            if substitution < best {
                best = substitution;
            }

            curr.push(best);
            j = j + 1;
        }

        prev = curr;
        i = i + 1;
    }

    return prev[m];
}

// Note: I don't know Kavach's exact syntax, so this assumes a Rust/Swift-like style.
// The top of the stack is the last element of `items`.
type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if len(self.items) == 0 {
            self
        } else {
            Stack { items: self.items[0..len(self.items) - 1] }
        }
    }

    fn top(self) -> Int? {
        if len(self.items) == 0 {
            None
        } else {
            Some(self.items[len(self.items) - 1])
        }
    }
}

