fn median(xs: [Float]) -> Float {
    let mut a = xs;
    let n = len(a);

    // insertion sort
    let mut i = 1;
    while i < n {
        let key = a[i];
        let mut j = i;
        while j > 0 && a[j - 1] > key {
            a[j] = a[j - 1];
            j = j - 1;
        }
        a[j] = key;
        i = i + 1;
    }

    let mid = n / 2;
    if n % 2 == 1 {
        return a[mid];
    }
    return (a[mid - 1] + a[mid]) / 2.0;
}

