fn pascal(n: Int) -> [Int] {
    let mut row: [Int] = [1];
    let mut i: Int = 0;
    while i < n {
        let mut next: [Int] = [1];
        let mut j: Int = 1;
        while j < len(row) {
            push(next, row[j - 1] + row[j]);
            j = j + 1;
        }
        push(next, 1);
        row = next;
        i = i + 1;
    }
    return row;
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Build a copy sorted by start using insertion sort
    let mut sorted: [(Int, Int)] = [];
    for x in xs {
        sorted.push(x);
        let mut j = sorted.len() - 1;
        while j > 0 && sorted[j - 1].0 > sorted[j].0 {
            let tmp = sorted[j - 1];
            sorted[j - 1] = sorted[j];
            sorted[j] = tmp;
            j = j - 1;
        }
    }

    // Merge overlapping or touching intervals
    let mut result: [(Int, Int)] = [];
    for iv in sorted {
        let n = result.len();
        if n > 0 && iv.0 <= result[n - 1].1 {
            if iv.1 > result[n - 1].1 {
                result[n - 1] = (result[n - 1].0, iv.1);
            }
        } else {
            result.push(iv);
        }
    }

    return result;
}

