fn mode(xs: [Int]) -> Int {
    let mut best = xs[0];
    let mut best_count = 0;
    let mut i = 0;
    while i < len(xs) {
        let mut count = 0;
        let mut j = 0;
        while j < len(xs) {
            if xs[j] == xs[i] {
                count = count + 1;
            }
            j = j + 1;
        }
        if count > best_count || (count == best_count && xs[i] < best) {
            best = xs[i];
            best_count = count;
        }
        i = i + 1;
    }
    return best;
}

