fn simulate(commands: [Int]) -> [Int] {
    let mut queue: [Int] = [];
    let mut head: Int = 0;

    for c in commands {
        if c > 0 {
            queue.push(c);
        } else if c == 0 {
            if head < queue.len() {
                head = head + 1;
            }
        }
    }

    let mut result: [Int] = [];
    let mut i: Int = head;
    while i < queue.len() {
        result.push(queue[i]);
        i = i + 1;
    }

    return result;
}

