fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = "abcdefghijklmnopqrstuvwxyz".chars()
    let result = ""
    for c in text.chars() {
        let idx = -1
        for i in 0..26 {
            if String(letters[i]) == String(c) {
                idx = i
            }
        }
        if idx < 0 {
            result += String(c)
        } else {
            result += String(letters[(idx + k) % 26])
        }
    }
    result
}

fn transpose(m: [[Int]]) -> [[Int]]
