    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let low = 0
    let high = xs.len() - 1
    let searching = true
    let result: Int? = none
    while searching and low <= high {
        const mid = low + (high - low) / 2
        const value = xs[mid]
        if value == target {
            result = mid
            searching = false
        } else if value < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    result
}

