    }
    result
}

fn title(text: String) -> String {
    const lowers = "abcdefghijklmnopqrstuvwxyz"
    const uppers = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let out: [String] = []
    for word in text.split(" ") {
        let piece = ""
        let first = true
        for c in word.chars() {
            const ch = String(c)
            if first {
                piece = piece + convert(ch, lowers, uppers)
            } else {
                piece = piece + convert(ch, uppers, lowers)
            }
            first = false
        }
        out.push(piece)
    }
    out.join(" ")
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    if n < 4 {
        return true
    }
    if n % 2 == 0 {
        return false
    }
    let i = 3
    while i * i <= n {
        if n % i == 0 {
            return false
        }
        i += 2
    }
    true
}

fn primes_below(n: Int) -> [Int] {
    let composite: [Bool] = []
    for _ in 0..n {
        composite.push(false)
    }

    let result: [Int] = []
    for i in 2..n {
        if not composite[i] {
            result.push(i)
            let j = i * i
            while j < n {
                composite[j] = true
                j += i
            }
        }
    }
    result
}

