fn rle(text: String) -> String {
    const chars = text.chars()
    let result = ""
    let i = 0
    while i < chars.len() {
        let j = i
        while j < chars.len() and chars[j] == chars[i] {
            j += 1
        }
        result += "{chars[i]}{j - i}"
        i = j
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        if c == "(" or c == "[" or c == "{" {
            stack.push(c)
        } else if c == ")" or c == "]" or c == "}" {
            const want = if c == ")" { "(" } else if c == "]" { "[" } else { "{" }
            const top = stack.pop() ?? ""
            if top != want {
                ok = false
                break
            }
        }
    }
    ok and stack.len() == 0
}

