fn distance(a: String, b: String) -> Int {
    const x = a.chars()
    const y = b.chars()
    let prev: [Int] = []
    for j in 0..(y.len() + 1) {
        prev.push(j)
    }
    for i in 1..(x.len() + 1) {
        let cur: [Int] = [i]
        for j in 1..(y.len() + 1) {
            const cost = if x[i - 1] == y[j - 1] { 0 } else { 1 }
            const deletion = prev[j] + 1
            const insertion = cur[j - 1] + 1
            const substitution = prev[j - 1] + cost
            let best = deletion
            if insertion < best {
                best = insertion
            }
            if substitution < best {
                best = substitution
            }
            cur.push(best)
        }
        prev = cur
    }
    prev[y.len()]
}

type Stack {
