fn median(xs: [Float]) -> Float
    require xs.len() > 0
{
    let sorted = xs
    let i = 1
    while i < sorted.len() {
        const key = sorted[i]
        let j = i - 1
        while j >= 0 and sorted[j] > key {
            sorted[j + 1] = sorted[j]
            j -= 1
        }
        sorted[j + 1] = key
        i += 1
    }
    const n = sorted.len()
    const mid = n / 2
    if n % 2 == 1 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

