}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let sorted: [(Int, Int)] = []
    for (s, e) in xs {
        let next: [(Int, Int)] = []
        let placed = false
        for (ys, ye) in sorted {
            if not placed and s < ys {
                next.push((s, e))
                placed = true
            }
            next.push((ys, ye))
        }
        if not placed {
            next.push((s, e))
        }
        sorted = next
    }

    let out: [(Int, Int)] = []
    for (s, e) in sorted {
        if let (ls, le) = out.pop() {
            if s <= le {
                const hi = if e > le { e } else { le }
                out.push((ls, hi))
            } else {
                out.push((ls, le))
                out.push((s, e))
            }
        } else {
            out.push((s, e))
        }
    }
    out
}

