        for j in 0..n {
            const higher = players[j].score > players[i].score
            const earlier_tie = players[j].score == players[i].score and j < i
            if higher or earlier_tie {
                rank += 1
            }
        }
        ranks.push(rank)
    }
    let names: [String] = []
    let r = 0
    while r < k and r < n {
        for i in 0..n {
            if ranks[i] == r {
                names.push(players[i].name)
            }
        }
        r += 1
    }
    names
}

