            }
        }
        result = "{result}{out}"
    }
    result
}

fn transpose(m: [[Int]]) -> [[Int]]
    require m.len() > 0
{
    let result: [[Int]] = []
    for c in 0..m[0].len() {
        let column: [Int] = []
        for row in m {
            column.push(row[c])
        }
        result.push(column)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let low = 0
    let high = xs.len() - 1
    let result: Int? = none
    while low <= high {
        const mid = low + (high - low) / 2
        const value = xs[mid]
        if value == target {
            result = mid
            break
        } else if value < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    result
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
