fn shift(ch: Char, from: [Char], to: [Char]) -> Char {
    let result = ch
    for i in 0..from.len() {
        if from[i] == ch {
            result = to[i]
        }
    }
    result
}

fn title(text: String) -> String {
    const lowers = "abcdefghijklmnopqrstuvwxyz".chars()
    const uppers = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars()
    let out: [String] = []
    for word in text.split(" ") {
        let piece = ""
        let first = true
        for ch in word.chars() {
            if first {
                const c = shift(ch, lowers, uppers)
                piece = "{piece}{c}"
            } else {
                const c = shift(ch, uppers, lowers)
                piece = "{piece}{c}"
            }
            first = false
        }
        out.push(piece)
    }
    out.join(" ")
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else if n < 4 {
        true
    } else if n % 2 == 0 {
        false
    } else {
        let i = 3
        let prime = true
        while prime and i <= n / i {
            if n % i == 0 {
                prime = false
            }
            i += 2
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let is_prime: [Bool] = []
    for _ in 0..n {
        is_prime.push(true)
    }
    let result: [Int] = []
    for i in 2..n {
        if is_prime[i] {
            result.push(i)
            let j = i * i
            while j < n {
                is_prime[j] = false
                j += i
            }
        }
    }
    result
}

pub fn digit_sum(n: Int) -> Int
    require n >= 0
    example digit_sum(0) == 0
    example digit_sum(123) == 6
{
    let total = 0
    let rest = n
    while rest > 0 {
        total += rest % 10
        rest = rest / 10
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let run = 0
    for ch in text.chars() {
        const piece = "{ch}"
        if run > 0 and piece == current {
            run += 1
        } else {
            if run > 0 {
                result = "{result}{current}{run}"
            }
            current = piece
            run = 1
        }
    }
    if run > 0 {
        result = "{result}{current}{run}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        const s = String(c)
        if s == "(" {
            stack.push(")")
        } else if s == "[" {
            stack.push("]")
        } else if s == "\{" {
            stack.push("}")
        } else if s == ")" or s == "]" or s == "}" {
            if let expected = stack.pop() {
                if expected != s {
                    ok = false
                    break
                }
            } else {
                ok = false
                break
            }
        }
    }
    ok and stack.len() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let found: (Int, Int)? = none
    const n = xs.len()
    outer: for i in 0..n {
        for j in (i + 1)..n {
            if xs[i] + xs[j] == target {
                found = (i, j)
                break outer
            }
        }
    }
    found
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    let remaining = n
    let result = ""
    for (value, symbol) in table {
        while remaining >= value {
            result = result + symbol
            remaining -= value
        }
    }
    result
}

