fn kth_smallest(xs: [Float], k: Int) -> Float {
    const found = xs.find(x => xs.count(y => y < x) <= k and k < xs.count(y => y <= x))
    found ?? 0.0
}

fn median(xs: [Float]) -> Float
    require xs.len() > 0
{
    const n = xs.len()
    const mid = n / 2
    if n % 2 == 1 {
        kth_smallest(xs, mid)
    } else {
        (kth_smallest(xs, mid - 1) + kth_smallest(xs, mid)) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row = [1]
    let step = 0
    while step < n {
        let next = [1]
        for i in 1..row.len() {
            next.push(row[i - 1] + row[i])
        }
        next.push(1)
        row = next
        step += 1
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let sorted: [(Int, Int)] = []
    for (s, e) in xs {
        let next: [(Int, Int)] = []
        let placed = false
        for (s2, e2) in sorted {
            if not placed and s < s2 {
                next.push((s, e))
                placed = true
            }
            next.push((s2, e2))
        }
        if not placed {
            next.push((s, e))
        }
        sorted = next
    }

    let result: [(Int, Int)] = []
    let has_current = false
    let cur_start = 0
    let cur_end = 0
    for (s, e) in sorted {
        if not has_current {
            cur_start = s
            cur_end = e
            has_current = true
        } else if s <= cur_end {
            if e > cur_end {
                cur_end = e
            }
        } else {
            result.push((cur_start, cur_end))
            cur_start = s
            cur_end = e
        }
    }
    if has_current {
        result.push((cur_start, cur_end))
    }
    result
}

fn last_or<T>(xs: [T], fallback: T) -> T {
