fn mode(xs: [Int]) -> Int
    require xs.len() > 0
{
    let best = xs[0]
    let best_count = xs.count(v => v == xs[0])
    for x in xs {
        const c = xs.count(y => y == x)
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
