pub fn collatz(n: Int) -> Int
    require n >= 1
    example collatz(1) == 0
    example collatz(6) == 8
    example collatz(27) == 111
{
    let current = n
    let steps = 0
    while current != 1 {
        if current % 2 == 0 {
            current = current / 2
        } else {
            current = 3 * current + 1
        }
        steps += 1
    }
    steps
}

