fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
    example caesar("abc xyz!", 3) == "def abc!"
{
    const alphabet = "abcdefghijklmnopqrstuvwxyz".chars()
    let out = ""
    for ch in text.chars() {
        let idx = -1
        for i in 0..26 {
            if alphabet[i] == ch {
                idx = i
            }
        }
        if idx >= 0 {
            out = "{out}{alphabet[(idx + k) % 26]}"
        } else {
            out = "{out}{ch}"
        }
    }
    out
}

pub fn transpose(m: [[Int]]) -> [[Int]]
    require m.len() >= 1
    require m.count(r => r.len() != m[0].len()) == 0
    ensure result.len() == m[0].len()
    example transpose([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]
    example transpose([[1]]) == [[1]]
{
    let result: [[Int]] = []
    for j in 0..m[0].len() {
        let col: [Int] = []
        for row in m {
            col.push(row[j])
        }
        result.push(col)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int?
    example find([1, 3, 5, 7], 5) == 2
    example find([1, 3, 5, 7], 4) == none
    example find([], 1) == none
{
    let lo = 0
    let hi = xs.len() - 1
    while lo <= hi {
        const mid = lo + (hi - lo) / 2
        const v = xs[mid]
        if v == target {
            return mid
        }
        if v < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    none
}

