    example common_prefix(["flower", "flow", "flight"]) == "fl"
    example common_prefix(["dog", "car"]) == ""
    example common_prefix(["abc"]) == "abc"
{
    if words.len() == 0 {
        ""
    } else {
        let prefix = words[0]
        for word in words {
            while not word.starts_with(prefix) {
                prefix = prefix.slice(0, prefix.len() - 1)
            }
        }
        prefix
    }
}

pub fn second_largest(xs: [Int]) -> Int? {
    let first: Int? = none
    let second: Int? = none
    for x in xs {
        if let f = first {
            if x > f {
                second = f
                first = x
            } else if x < f {
                if let s = second {
                    if x > s {
                        second = x
                    }
                } else {
                    second = x
                }
            }
        } else {
            first = x
        }
    }
    second
}

pub fn merge(a: [Int], b: [Int]) -> [Int]
    example merge([1, 3, 5], [2, 4]) == [1, 2, 3, 4, 5]
    example merge([], [1]) == [1]
    example merge([1, 1], [1]) == [1, 1, 1]
{
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

pub fn distance(a: String, b: String) -> Int
    ensure result >= 0
    example distance("kitten", "sitting") == 3
    example distance("", "abc") == 3
    example distance("same", "same") == 0
{
    const xs = a.chars()
    const ys = b.chars()
    const m = ys.len()
    let prev: [Int] = []
    for j in 0..(m + 1) {
        prev.push(j)
    }
    for i in 0..xs.len() {
        let cur: [Int] = [i + 1]
        for j in 0..m {
            const cost = if xs[i] == ys[j] { 0 } else { 1 }
            let best = prev[j] + cost
            if prev[j + 1] + 1 < best {
                best = prev[j + 1] + 1
            }
            if cur[j] + 1 < best {
                best = cur[j] + 1
            }
            cur.push(best)
        }
        prev = cur
    }
    prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            Stack(items: self.items.take(self.items.len() - 1))
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

