pub fn pascal(n: Int) -> [Int]
    require n >= 0 and n <= 66
    example pascal(0) == [1]
    example pascal(1) == [1, 1]
    example pascal(4) == [1, 4, 6, 4, 1]
{
    let row = [1]
    for _ in 0..n {
        let next = [1]
        for j in 1..row.len() {
            next.push(row[j - 1] + row[j])
        }
        next.push(1)
        row = next
    }
    row
}

pub fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)]
    example merge_intervals([(1, 3), (2, 6), (8, 10)]) == [(1, 6), (8, 10)]
    example merge_intervals([(1, 2), (2, 3)]) == [(1, 3)]
    example merge_intervals([]) == []
{
    const sorted = xs.sort_by(p => p.0)
    let result: [(Int, Int)] = []
    for p in sorted {
        const n = result.len()
        if n > 0 and p.0 <= result[n - 1].1 {
            const last = result[n - 1]
            if p.1 > last.1 {
                result[n - 1] = (last.0, p.1)
            }
        } else {
            result.push(p)
        }
    }
    result
}

