pub fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
    ensure result >= 0 and result <= 100
    example percent(1, 4) == 25
    example percent(1, 3) == 33
    example percent(5, 5) == 100
{
    // Adds `part` 100 times, tracking quotient and remainder against `whole`,
    // so part * 100 is never formed and cannot overflow.
    let q = 0
    let r = 0
    for _ in 0..100 {
        if r >= whole - part {
            q += 1
            r = r - (whole - part)
        } else {
            r += part
        }
    }
    q
}

