pub fn mode(xs: [Int]) -> Int
    require xs.len() > 0
    example mode([1, 2, 2, 3]) == 2
    example mode([3, 1, 3, 1]) == 1
    example mode([5]) == 5
{
    let counts: [Int: Int] = [:]
    for x in xs {
        counts[x] = (counts[x] ?? 0) + 1
    }
    let best = xs[0]
    let best_count = 0
    for (k, c) in counts {
        if c > best_count or (c == best_count and k < best) {
            best = k
            best_count = c
        }
    }
    best
}

