    example top([Player(name: "a", score: 1), Player(name: "b", score: 3), Player(name: "c", score: 3), Player(name: "d", score: 2)], 3) == ["b", "c", "d"]
    example top([Player(name: "a", score: 1)], 5) == ["a"]
