{
    let sorted: [Player] = []
    for p in players {
        let pos = sorted.len()
        while pos > 0 and sorted[pos - 1].score < p.score {
            pos -= 1
        }
        let result: [Player] = sorted.take(pos)
        result.push(p)
        result += sorted.skip(pos)
        sorted = result
    }
    if k <= 0 {
        []
    } else {
        sorted.take(k).map(.name)
    }
}

