// adjust keywords (e.g. `let mut`, `len`) if your Kavach version differs.
fn find(xs: [Int], target: Int) -> Int? {
    let mut lo: Int = 0
    let mut hi: Int = len(xs) - 1

    while lo <= hi {
        let mid: Int = lo + (hi - lo) / 2
        let v: Int = xs[mid]

        if v == target {
            return mid
        } else if v < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }

    return none
}

