fn primes_below(n: Int) -> [Int] {
    let mut primes: [Int] = [];
    let mut candidate = 2;
    while candidate < n {
        let mut is_prime = true;
        let mut i = 0;
        while i < primes.len() {
            let p = primes[i];
            if p * p > candidate {
                break;
            }
            if candidate % p == 0 {
                is_prime = false;
                break;
            }
            i = i + 1;
        }
        if is_prime {
            primes.push(candidate);
        }
        candidate = candidate + 1;
    }
    return primes;
}

