fn balanced(text: String) -> Bool {
    let mut stack: Vec<Char> = Vec::new();
    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}' {
            if stack.len() == 0 {
                return false;
            }
            let open = stack.pop();
            if (c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{') {
                return false;
            }
        }
    }
    return stack.len() == 0;
}

