fn distance(a: String, b: String) -> Int {
    let s = a.chars();
    let t = b.chars();
    let n = s.len();
    let m = t.len();

    let mut prev = [];
    let mut j = 0;
    while j <= m {
        prev.push(j);
        j = j + 1;
    }

    let mut i = 1;
    while i <= n {
        let mut curr = [i];
        let mut k = 1;
        while k <= m {
            let cost = if s[i - 1] == t[k - 1] { 0 } else { 1 };
            let del = prev[k] + 1;
            let ins = curr[k - 1] + 1;
            let sub = prev[k - 1] + cost;
            let mut best = del;
            if ins < best { best = ins; }
            if sub < best { best = sub; }
            curr.push(best);
            k = k + 1;
        }
        prev = curr;
        i = i + 1;
    }

    return prev[m];
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        return Stack { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            return self
        }
        return Stack { items: self.items[0 .. self.items.len() - 1] }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            return none
        }
        return self.items[self.items.len() - 1]
    }
}

