// Each entry uses C(n, k+1) = C(n, k) * (n - k) / (k + 1).
fn pascal(n: Int) -> [Int] {
    let mut row: [Int] = [1];
    let mut c: Int = 1;
    let mut k: Int = 0;
    while k < n {
        c = c * (n - k) / (k + 1);
        row.push(c);
        k = k + 1;
    }
    return row;
}

