// You may need to adjust it, especially mutability, `push`, `len`,
// tuple field access, and `for` loops.
fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Copy the input so it can be sorted in place.
    let mut sorted: [(Int, Int)] = [];
    for x in xs {
        sorted.push(x);
    }

    // Insertion sort by start (avoids relying on library sort APIs).
    let n = sorted.len();
    let mut i = 1;
    while i < n {
        let cur = sorted[i];
        let mut j = i;
        while j > 0 && sorted[j - 1].0 > cur.0 {
            sorted[j] = sorted[j - 1];
            j = j - 1;
        }
        sorted[j] = cur;
        i = i + 1;
    }

    // Merge overlapping or touching intervals.
    let mut result: [(Int, Int)] = [];
    for iv in sorted {
        let k = result.len();
        if k > 0 && iv.0 <= result[k - 1].1 {
            let last = result[k - 1];
            if iv.1 > last.1 {
                result[k - 1] = (last.0, iv.1);
            }
        } else {
            result.push(iv);
        }
    }

    result
}

