    while m > 0 {
        if m % 2 == 1 {
            s = "1" + s;
        } else {
            s = "0" + s;
        }
        m = m / 2;
    }
    return s;
}

fn mode(xs: [Int]) -> Int {
    let mut best = xs[0];
    let mut best_count = 0;
    let mut i = 0;
    while i < xs.len() {
        let x = xs[i];
        let mut count = 0;
        let mut j = 0;
        while j < xs.len() {
            if xs[j] == x {
                count = count + 1;
            }
            j = j + 1;
        }
        if count > best_count || (count == best_count && x < best) {
            best = x;
            best_count = count;
        }
        i = i + 1;
    }
    return best;
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let mut result: [String: Int] = [:]
    let n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    return result
}

// Note: I'm not familiar with Kavach's exact syntax, so this assumes Rust-like
