fn simulate(commands: [Int]) -> [Int] {
    let mut queue: [Int] = [];
    let mut head = 0;

    for c in commands {
        if c > 0 {
            queue.push(c);
        } else if c == 0 {
            if head < queue.len() {
                head += 1;
            }
        }
    }

    let mut result: [Int] = [];
    let mut i = head;
    while i < queue.len() {
        result.push(queue[i]);
        i += 1;
    }
    return result;
}

