fn is_palindrome(text: String) -> Bool {
    const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars()
    const lower = "abcdefghijklmnopqrstuvwxyz".chars()
    let folded = text.chars()
    for i in 0..folded.len() {
        for j in 0..upper.len() {
            if folded[i] == upper[j] {
                folded[i] = lower[j]
                break
            }
        }
    }
    const n = folded.len()
    let same = true
    for i in 0..n / 2 {
        if folded[i] != folded[n - 1 - i] {
            same = false
            break
        }
    }
    same
}

