fn caesar(text: String, k: Int) -> String {
    const letters = "abcdefghijklmnopqrstuvwxyz".chars()
    let out = ""
    for c in text.chars() {
        let shifted = String(c)
        for i in 0..26 {
            if letters[i] == c {
                shifted = String(letters[(i + k) % 26])
                break
            }
        }
        out += shifted
    }
    out
}

