fn title(text: String) -> String {
    const lower = "abcdefghijklmnopqrstuvwxyz"
    const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let result = ""
    let at_word_start = true
    for ch in text.chars() {
        const c = String(ch)
        if c == " " {
            result = result + c
            at_word_start = true
        } else if at_word_start {
            result = result + swap_case_letter(c, lower, upper)
            at_word_start = false
        } else {
            result = result + swap_case_letter(c, upper, lower)
        }
    }
    result
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else if n < 4 {
        true
    } else if n % 2 == 0 or n % 3 == 0 {
        false
    } else {
        let i = 5
        let prime = true
        while prime and i <= n / i {
            if n % i == 0 or n % (i + 2) == 0 {
                prime = false
            }
            i += 6
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        for p in primes {
            if p * p > candidate {
                break
            }
            if candidate % p == 0 {
                is_prime = false
                break
            }
        }
        if is_prime {
            primes.push(candidate)
        }
        candidate += 1
    }
    primes
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    for c in text.chars() {
        const ch = String(c)
        if count > 0 and ch == current {
            count += 1
        } else {
            if count > 0 {
                result = result + "{current}{count}"
            }
            current = ch
            count = 1
        }
    }
    if count > 0 {
        result = result + "{current}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        const ch = String(c)
        if ch == "(" or ch == "[" or ch == "{" {
            stack.push(ch)
        } else if ch == ")" or ch == "]" or ch == "}" {
            const expected = if ch == ")" { "(" } else if ch == "]" { "[" } else { "{" }
            const open = stack.pop() ?? ""
            if open != expected {
                ok = false
                break
            }
        }
    }
    ok and stack.len() == 0
}

