    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    result += a.skip(i)
    result += b.skip(j)
    result
}

fn distance(a: String, b: String) -> Int {
    const s = a.chars()
    const t = b.chars()
    const n = s.len()
    const m = t.len()
    let prev: [Int] = []
    for j in 0..(m + 1) {
        prev.push(j)
    }
    for i in 1..(n + 1) {
        let cur: [Int] = [i]
        for j in 1..(m + 1) {
            const cost = if s[i - 1] == t[j - 1] { 0 } else { 1 }
            let best = prev[j] + 1
            const insert = cur[j - 1] + 1
            if insert < best {
                best = insert
            }
            const substitute = prev[j - 1] + cost
            if substitute < best {
                best = substitute
            }
            cur.push(best)
        }
        prev = cur
    }
    prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        self with { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        let items = self.items
        const _ = items.pop()
        self with { items: items }
    }

    fn top(self) -> Int? {
        let items = self.items
        items.pop()
    }
}

