fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Insertion sort by start. Equal starts keep their input order.
    let sorted: [(Int, Int)] = []
    for (lo, hi) in xs {
        let next: [(Int, Int)] = []
        let placed = false
        for (a, b) in sorted {
            if not placed and a > lo {
                next.push((lo, hi))
                placed = true
            }
            next.push((a, b))
        }
        if not placed {
            next.push((lo, hi))
        }
        sorted = next
    }

    // Merge overlapping or touching intervals.
    let result: [(Int, Int)] = []
    let has_current = false
    let cur_lo = 0
    let cur_hi = 0
    for (lo, hi) in sorted {
        if not has_current {
            cur_lo = lo
            cur_hi = hi
            has_current = true
        } else if lo <= cur_hi {
            if hi > cur_hi {
                cur_hi = hi
            }
        } else {
            result.push((cur_lo, cur_hi))
            cur_lo = lo
            cur_hi = hi
        }
    }
    if has_current {
        result.push((cur_lo, cur_hi))
    }
    result
}

