// NOTE: the Kavach guide does not cover concurrency, so `spawn` and
// `.await()` below are assumed syntax. Check docs/spec/ for the real form.

fn sum_squares(low: Int, high: Int) -> Int {
    let total = 0
    let i = low
    while i <= high {
        total += i * i
        i += 1
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const first = spawn sum_squares(1, mid)
    const rest = spawn sum_squares(mid + 1, n)
    const a = try first.await()
    const b = try rest.await()
    a + b
}

