fn top(players: [Player], k: Int) -> [String] {
    let sorted: [Player] = []
    for p in players {
        let next: [Player] = []
        let placed = false
        for q in sorted {
            if not placed and p.score > q.score {
                next.push(p)
                placed = true
            }
            next.push(q)
        }
        if not placed {
            next.push(p)
        }
        sorted = next
    }
    let names: [String] = []
    for p in sorted {
        if names.len() >= k {
            break
        }
        names.push(p.name)
    }
    names
}

