fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    let found: Int? = none
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        const value = xs[mid]
        if value == target {
            found = mid
            break
        } else if value < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    found
}

