fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    if n < 4 {
        return true
    }
    if n % 2 == 0 or n % 3 == 0 {
        return false
    }
    let i = 5
    while i <= n / i {
        if n % i == 0 or n % (i + 2) == 0 {
            return false
        }
        i += 6
    }
    true
}

fn primes_below(n: Int) -> [Int] {
    let sieve: [Bool] = []
    let fill = 0
    while fill < n {
        sieve.push(true)
        fill += 1
    }
    let i = 2
    while i * i < n {
        if sieve[i] {
            let j = i * i
            while j < n {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let result: [Int] = []
    let k = 2
    while k < n {
        if sieve[k] {
            result.push(k)
        }
        k += 1
    }
    result
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    for c in text.chars() {
        const s = String(c)
        if count > 0 and s == current {
            count += 1
        } else {
            if count > 0 {
                result = result + "{current}{count}"
            }
            current = s
            count = 1
        }
    }
    if count > 0 {
        result = result + "{current}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [Int] = []
    let ok = true
    for c in text.chars() {
        const s = String(c)
        if s == "(" {
            stack.push(1)
        } else if s == "[" {
            stack.push(2)
        } else if s == "\{" {
            stack.push(3)
        } else if s == ")" {
            if (stack.pop() ?? 0) != 1 {
                ok = false
            }
        } else if s == "]" {
            if (stack.pop() ?? 0) != 2 {
                ok = false
            }
        } else if s == "}" {
            if (stack.pop() ?? 0) != 3 {
                ok = false
            }
        }
    }
    ok and stack.len() == 0
}

