    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    const n = xs.len()
    const m = ys.len()

    let prev: [Int] = []
    for j in 0..(m + 1) {
        prev.push(j)
    }

    for i in 1..(n + 1) {
        let curr: [Int] = [i]
        for j in 1..(m + 1) {
            const cost = if xs[i - 1] == ys[j - 1] { 0 } else { 1 }
            const deletion = prev[j] + 1
            const insertion = curr[j - 1] + 1
            const substitution = prev[j - 1] + cost
            let best = deletion
            if insertion < best {
                best = insertion
            }
            if substitution < best {
                best = substitution
            }
            curr.push(best)
        }
        prev = curr
    }

    prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        self with { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            self with { items: self.items.take(self.items.len() - 1) }
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

