fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let sorted = xs
    let i = 1
    while i < sorted.len() {
        let j = i
        while j > 0 and start_of(sorted[j - 1]) > start_of(sorted[j]) {
            const tmp = sorted[j]
            sorted[j] = sorted[j - 1]
            sorted[j - 1] = tmp
            j -= 1
        }
        i += 1
    }

    let result: [(Int, Int)] = []
    let have = false
    let cur_start = 0
    let cur_end = 0
    for (s, e) in sorted {
        if not have {
            cur_start = s
            cur_end = e
            have = true
        } else if s <= cur_end {
            if e > cur_end {
                cur_end = e
            }
        } else {
            result.push((cur_start, cur_end))
            cur_start = s
            cur_end = e
        }
    }
    if have {
        result.push((cur_start, cur_end))
    }
    result
}

