fn squares(n: Int) -> Int ! Error
    require n >= 0
{
    const mid = n / 2
    // The task syntax isn't in the guide, so these two run one after the other.
    // Each is pure and independent: start them as two concurrent tasks here.
    const first_half = sum_squares(1, mid)
    const second_half = sum_squares(mid + 1, n)
    first_half + second_half
}

fn total_qty(text: String) -> Int {
    match json.decode<[Item]>(text) {
        ok(items) => items.sum(.qty)
        err(_) => -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let running: Decimal = 0
    for (price, quantity) in items {
        running += price * Decimal(quantity)
    }
    running
}

fn deposit(a: Account, amount: Int) -> Account {
    a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    if xs.len() >= 2 {
        const last = xs.len() - 1
        const first = xs[0]
        xs[0] = xs[last]
        xs[last] = first
    }
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let result: [String] = []
    for (key, value) in m {
        if value >= min {
            result = result.filter(x => x < key) + [key] + result.filter(x => x >= key)
        }
    }
    result
}

fn numbered(items: [String]) -> String {
    let lines: [String] = []
    let i = 1
    for item in items {
        lines.push("{i}. {item}")
        i += 1
    }
    lines.join("\n")
}

fn add_or_none(a: Int, b: Int) -> Int? {
    const max = 9_223_372_036_854_775_807
    const min = -max - 1
    if b > 0 and a > max - b {
        none
    } else if b < 0 and a < min - b {
        none
    } else {
        a + b
    }
}

fn adder(step: Int) -> fn(Int) -> Int {
