fn is_power_of_two(n: Int) -> Bool {
    if n <= 0 {
        false
    } else {
        let m = n
        while m % 2 == 0 {
            m = m / 2
        }
        m == 1
    }
}

fn binary(n: Int) -> String
    require n >= 0
{
    if n == 0 {
        "0"
    } else {
        let m = n
        let text = ""
        while m > 0 {
            text = "{m % 2}{text}"
            m = m / 2
        }
        text
    }
}

fn mode(xs: [Int]) -> Int
    require xs.len() > 0
{
    let best = xs[0]
    let best_count = 0
    for x in xs {
        const c = xs.count(y => y == x)
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    const n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 {
        return "invalid"
    }
    // Written as differences so large inputs can't overflow (all sides are positive here)
    if a - b >= c or b - a >= c or c - a >= b {
        return "invalid"
    }
    if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn lengths(text: String) -> [Int] {
    let result: [Int] = []
    if text.len() > 0 {
        for word in text.split(" ") {
            result.push(word.len())
        }
    }
    result
}

fn collatz(n: Int) -> Int
    require n >= 1
    ensure result >= 0
    example collatz(1) == 0
    example collatz(6) == 8
{
    let current = n
    let steps = 0
    while current != 1 {
        current = if current % 2 == 0 { current / 2 } else { 3 * current + 1 }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int {
    const digits = "0123456789".chars()
    let total = 0
    for c in text.chars() {
        for i in 0..10 {
            if digits[i] == c {
                total += i
            }
        }
    }
    total
}

fn top(players: [Player], k: Int) -> [String] {
    const n = players.len()
    const limit = if k < n { k } else { n }
    let used: [Bool] = []
    for i in 0..n {
        used.push(false)
    }
    let result: [String] = []
    let picked = 0
    while picked < limit {
        let best = -1
        for j in 0..n {
            if not used[j] {
                if best < 0 or players[j].score > players[best].score {
                    best = j
                }
            }
        }
        used[best] = true
        result.push(players[best].name)
        picked += 1
    }
    result
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    require lo <= hi
    ensure result.len() == xs.len()
    example clamp_all([1, 5, 10], 2, 8) == [2, 5, 8]
{
    let result: [Int] = []
    for x in xs {
        const clamped = if x < lo { lo } else if x > hi { hi } else { x }
        result.push(clamped)
    }
    result
}

fn is_sorted(xs: [Int]) -> Bool {
    if xs.len() < 2 {
        true
    } else {
        let sorted = true
        for i in 1..xs.len() {
            if xs[i - 1] > xs[i] {
                sorted = false
                break
            }
        }
        sorted
    }
}

fn simulate(commands: [Int]) -> [Int] {
    let queue: [Int] = []
    for command in commands {
        if command > 0 {
            queue.push(command)
        } else if command == 0 and queue.len() > 0 {
            queue = queue.skip(1)
        }
    }
    queue
}

fn sum_evens(xs: [Int]) -> Int
    require xs.len() <= 1_000_000
    require xs.count(x => x > 1_000_000_000_000 or x < -1_000_000_000_000) == 0
    example sum_evens([1, 2, 3, 4]) == 6
    example sum_evens([]) == 0
    example sum_evens([-2, 5]) == -2
{
    let total = 0
    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String
