    example reverse_words("") == ""
    example reverse_words("one") == "one"
{
    const words = text.split(" ")
    let out: [String] = []
    let i = words.len() - 1
    while i >= 0 {
        out.push(words[i])
        i -= 1
    }
    out.join(" ")
}

fn is_palindrome(text: String) -> Bool
