    example is_palindrome("abc") == false
    example is_palindrome("") == true
{
    const cs = text.lower().chars()
    let i = 0
    let j = cs.len() - 1
    while i < j {
        if cs[i] != cs[j] {
            return false
        }
        i += 1
        j -= 1
    }
    true
}

