fn fib(n: Int) -> Int
    require n >= 0 and n <= 92
    example fib(0) == 0
    example fib(1) == 1
    example fib(10) == 55
{
    if n == 0 {
        return 0
    }
    let a = 0
    let b = 1
    for _ in 1..n {
        const t = a + b
        a = b
        b = t
    }
    b
}

fn by_length(words: [String]) -> [String]
    example by_length(["ccc", "a", "bb", "d"]) == ["a", "d", "bb", "ccc"]
{
    let result: [String] = []
    for w in words {
        let i = result.len()
        result.push(w)
        while i > 0 and result[i - 1].len() > w.len() {
            result[i] = result[i - 1]
            i -= 1
        }
        result[i] = w
    }
    result
}

fn dedupe(xs: [Int]) -> [Int]
    example dedupe([1, 2, 1, 3, 2]) == [1, 2, 3]
    example dedupe([]) == []
{
    let seen: Set<Int> = Set.of()
    let out: [Int] = []
    for x in xs {
        if not seen.contains(x) {
            seen.add(x)
            out.push(x)
        }
    }
    out
}

