fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = "abcdefghijklmnopqrstuvwxyz".chars()
    let index: [String: Int] = [:]
    for i in 0..26 {
        index[String(letters[i])] = i
    }
    let out = ""
    for c in text.chars() {
        const s = String(c)
        if let i = index[s] {
            out += String(letters[(i + k) % 26])
        } else {
            out += s
        }
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]]
    require m.len() >= 1
    require m.all(.len() == m[0].len())
    example transpose([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]
{
    let result: [[Int]] = []
    const cols = m[0].len()
    for c in 0..cols {
        let row: [Int] = []
        for r in m {
            row.push(r[c])
        }
        result.push(row)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int?
    example find([1, 3, 5, 7], 5) == 2
    example find([1, 3, 5, 7], 4) == none
    example find([], 1) == none
{
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            return mid
        } else if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    none
}

fn divide(a: Int, b: Int) -> Int ! MathError {
