fn median(xs: [Float]) -> Float
    require xs.len() > 0
{
    const s = xs.sort()
    const n = s.len()
    if n % 2 != 0 {
        s[n / 2]
    } else {
        (s[n / 2 - 1] + s[n / 2]) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0 and n <= 66
    example pascal(0) == [1]
    example pascal(4) == [1, 4, 6, 4, 1]
{
    let row: [Int] = [1]
    for i in 0..n {
        let next: [Int] = [1]
        for k in 1..row.len() {
            next.push(row[k - 1] + row[k])
        }
        next.push(1)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)]
    example merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]
    example merge_intervals([(1, 4), (4, 5)]) == [(1, 5)]
    example merge_intervals([(5, 6), (1, 2)]) == [(1, 2), (5, 6)]
    example merge_intervals([]) == []
{
    const sorted = xs.sort_by(p => p.0)
    let out: [(Int, Int)] = []
    let started = false
    let cs = 0
    let ce = 0
    for (s, e) in sorted {
        if not started {
            cs = s
            ce = e
            started = true
        } else if s <= ce {
            if e > ce {
                ce = e
            }
        } else {
            out.push((cs, ce))
            cs = s
            ce = e
        }
    }
    if started {
        out.push((cs, ce))
    }
    out
}

fn last_or<T>(xs: [T], fallback: T) -> T
