fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
    ensure result >= 0 and result <= 100
    example percent(1, 3) == 33
    example percent(5, 5) == 100
    example percent(0, 7) == 0
    example percent(2, 3) == 66
{
    // Largest r with r * whole <= part * 100, computed without overflow:
    // whole = 100a + b, so ceil(r * whole / 100) = r * a + ceil(r * b / 100).
    const a = whole / 100
    const b = whole % 100
    let r = 100
    while r > 0 {
        if r * a + (r * b + 99) / 100 <= part {
            break
        }
        r -= 1
    }
    r
}

