fn binary(n: Int) -> String
    require n >= 0
    example binary(0) == "0"
    example binary(5) == "101"
    example binary(8) == "1000"
{
    if n == 0 {
        return "0"
    }
    let digits: [String] = []
    let m = n
    while m > 0 {
        digits.push(String(m % 2))
        m = m / 2
    }
    let out = ""
    let i = digits.len() - 1
    while i >= 0 {
        out = out + digits[i]
        i -= 1
    }
    out
}

fn mode(xs: [Int]) -> Int
    require xs.len() > 0
    example mode([1, 2, 2, 3]) == 2
    example mode([3, 1, 3, 1]) == 1
    example mode([5]) == 5
{
    let counts: [Int: Int] = [:]
    for x in xs {
        counts[x] = (counts[x] ?? 0) + 1
    }
    let best = xs[0]
    let best_count = 0
    for (k, c) in counts {
        if c > best_count or (c == best_count and k < best) {
            best = k
            best_count = c
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int]
