{
    let result: [String: Int] = [:]
    const n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String
    example triangle(2, 2, 2) == "equilateral"
    example triangle(3, 3, 5) == "isosceles"
    example triangle(3, 4, 5) == "scalene"
    example triangle(1, 2, 3) == "invalid"
    example triangle(0, 1, 1) == "invalid"
    example triangle(-1, 2, 2) == "invalid"
{
    if a <= 0 or b <= 0 or c <= 0 {
        return "invalid"
    }
    // a >= b + c rewritten as a - b >= c to avoid overflow (all sides positive)
    if a - b >= c or b - a >= c or c - a >= b {
        return "invalid"
    }
    if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

