fn collatz(n: Int) -> Int
    require n >= 1 and n <= 1_000_000_000
    ensure result >= 0
    example collatz(1) == 0
    example collatz(6) == 8
    example collatz(27) == 111
{
    let x = n
    let steps = 0
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = 3 * x + 1
        }
        steps += 1
    }
    steps
}

