fn top(players: [Player], k: Int) -> [String] {
    let sorted: [Player] = []
    for p in players {
        let i = sorted.len()
        sorted.push(p)
        while i > 0 and sorted[i - 1].score < p.score {
            sorted[i] = sorted[i - 1]
            i -= 1
        }
        sorted[i] = p
    }
    let result: [String] = []
    let n = 0
    for p in sorted {
        if n >= k {
            break
        }
        result.push(p.name)
        n += 1
    }
    result
}

