fn caesar(text: String, k: Int) -> String {
    let mut result: String = "";
    for ch in text.chars() {
        if ch >= 'a' && ch <= 'z' {
            let shifted: Int = (ch.to_int() - 'a'.to_int() + k) % 26;
            result = result + Char.from_int('a'.to_int() + shifted).to_string();
        } else {
            result = result + ch.to_string();
        }
    }
    return result;
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let rows = len(m);
    let cols = len(m[0]);
    let mut result: [[Int]] = [];
    let mut j = 0;
    while j < cols {
        let mut col: [Int] = [];
        let mut i = 0;
        while i < rows {
            col.push(m[i][j]);
            i = i + 1;
        }
        result.push(col);
        j = j + 1;
    }
    return result;
}

fn search(xs: [Int], target: Int, lo: Int, hi: Int) -> Int? {
    if lo >= hi {
        return none
    }
    let mid = lo + (hi - lo) / 2
    if xs[mid] == target {
        return mid
    }
    if xs[mid] < target {
        return search(xs, target, mid + 1, hi)
    }
    return search(xs, target, lo, mid)
}

fn find(xs: [Int], target: Int) -> Int? {
