fn no_divisor_from(n: Int, d: Int) -> Bool {
    if (d * d > n) {
        return true;
    }
    if (n % d == 0) {
        return false;
    }
    if (n % (d + 2) == 0) {
        return false;
    }
    return no_divisor_from(n, d + 6);
}

fn is_prime(n: Int) -> Bool {
    if (n < 2) {
        return false;
    }
    if (n < 4) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    if (n % 3 == 0) {
        return false;
    }
    return no_divisor_from(n, 5);
}

fn primes_below(n: Int) -> [Int] {
    let mut result: [Int] = [];
    let mut i = 2;
    while i < n {
        let mut is_prime = true;
        let mut d = 2;
        while d * d <= i {
            if i % d == 0 {
                is_prime = false;
                break;
            }
            d = d + 1;
        }
        if is_prime {
            result.push(i);
        }
        i = i + 1;
    }
    return result;
}

fn digit_sum(n: Int) -> Int {
    if n < 10 {
        return n
    }
    return n % 10 + digit_sum(n / 10)
}

fn rle(text: String) -> String {
    let mut out = String::new();
    let mut chars = text.chars();

    let mut current = match chars.next() {
        Some(c) => c,
        None => return out,
    };
    let mut count: usize = 1;

    for c in chars {
        if c == current {
            count += 1;
        } else {
            out.push(current);
            out.push_str(&count.to_string());
            current = c;
            count = 1;
        }
    }

    out.push(current);
    out.push_str(&count.to_string());
    out
}

fn balanced(text: String) -> Bool {
    let mut stack: List<Char> = [];

    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}' {
            if stack.is_empty() {
                return false;
            }
            let open = stack.pop();
            if c == ')' && open != '(' {
                return false;
            }
            if c == ']' && open != '[' {
                return false;
            }
            if c == '}' && open != '{' {
                return false;
            }
        }
    }

    return stack.is_empty();
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let n = xs.len()
    var i = 0
    while i < n {
        var j = i + 1
        while j < n {
            if xs[i] + xs[j] == target {
                return (i, j)
            }
            j = j + 1
        }
        i = i + 1
    }
    return none
}

