fn roman(n: Int) -> String {
    if (n >= 1000) { return "M" + roman(n - 1000); }
    if (n >= 900) { return "CM" + roman(n - 900); }
    if (n >= 500) { return "D" + roman(n - 500); }
    if (n >= 400) { return "CD" + roman(n - 400); }
    if (n >= 100) { return "C" + roman(n - 100); }
    if (n >= 90) { return "XC" + roman(n - 90); }
    if (n >= 50) { return "L" + roman(n - 50); }
    if (n >= 40) { return "XL" + roman(n - 40); }
    if (n >= 10) { return "X" + roman(n - 10); }
    if (n >= 9) { return "IX" + roman(n - 9); }
    if (n >= 5) { return "V" + roman(n - 5); }
    if (n >= 4) { return "IV" + roman(n - 4); }
    if (n >= 1) { return "I" + roman(n - 1); }
    return "";
}

fn flatten(xss: [[Int]]) -> [Int] {
    let mut result: [Int] = [];
    for xs in xss {
        for x in xs {
            result.push(x);
        }
    }
    return result;
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let mut result: [[Int]] = [];
    let mut current: [Int] = [];
    let mut i = 0;
    while i < len(xs) {
        current = current + [xs[i]];
        if len(current) == n {
            result = result + [current];
            current = [];
        }
        i = i + 1;
    }
    if len(current) > 0 {
        result = result + [current];
    }
    return result;
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    let n = len(xs)
    if n == 0 {
        return xs
    }
    let s = k % n
    let mut out: [Int] = []
    let mut i = 0
    while i < n {
        out.push(xs[(i + s) % n])
        i = i + 1
    }
    return out
}

fn common_prefix(words: [String]) -> String {
    if words.len() == 0 {
        return "";
    }
    let mut prefix = words[0];
    for word in words {
        while !word.starts_with(prefix) {
            prefix = prefix.substring(0, prefix.len() - 1);
        }
    }
    return prefix;
}

fn second_largest(xs: [Int]) -> Int? {
    let mut have_best = false
    let mut have_second = false
    let mut best = 0
    let mut second = 0

    for x in xs {
        if !have_best {
            best = x
            have_best = true
        } else if x > best {
            second = best
            have_second = true
            best = x
        } else if x < best && (!have_second || x > second) {
            second = x
            have_second = true
        }
    }

    if have_second {
        return second
    }
    return none
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let mut result: [Int] = [];
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i]);
            i = i + 1;
        } else {
            result.push(b[j]);
            j = j + 1;
        }
    }

    while i < a.len() {
        result.push(a[i]);
        i = i + 1;
    }

    while j < b.len() {
        result.push(b[j]);
        j = j + 1;
    }

    return result;
}

fn distance(a: String, b: String) -> Int {
    let n = a.len();
    let m = b.len();

    if n == 0 {
        return m;
    }
    if m == 0 {
        return n;
    }

    let mut prev: [Int] = [];
    let mut j = 0;
    while j <= m {
        prev.push(j);
        j = j + 1;
    }

    let mut i = 1;
    while i <= n {
        let mut curr: [Int] = [];
        curr.push(i);

        j = 1;
        while j <= m {
            let mut cost = 1;
            if a[i - 1] == b[j - 1] {
                cost = 0;
            }

            let mut best = prev[j] + 1;
            if curr[j - 1] + 1 < best {
                best = curr[j - 1] + 1;
            }
            if prev[j - 1] + cost < best {
                best = prev[j - 1] + cost;
            }

            curr.push(best);
            j = j + 1;
        }

        prev = curr;
        i = i + 1;
    }

    return prev[m];
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        return Stack { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            return self
        }
        return Stack { items: self.items[0..self.items.len() - 1] }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            return nil
        }
        return self.items[self.items.len() - 1]
    }
}

