fn kth_smallest(xs: [Float], k: Int) -> Float {
    let n = xs.len();
    let mut i = 0;
    while i < n {
        let mut less = 0;
        let mut equal = 0;
        let mut j = 0;
        while j < n {
            if xs[j] < xs[i] {
                less = less + 1;
            }
            if xs[j] == xs[i] {
                equal = equal + 1;
            }
            j = j + 1;
        }
        if less <= k && k < less + equal {
            return xs[i];
        }
        i = i + 1;
    }
    return xs[0];
}

fn median(xs: [Float]) -> Float {
    let n = xs.len();
    let mid = n / 2;
    if n % 2 == 1 {
        return kth_smallest(xs, mid);
    }
    return (kth_smallest(xs, mid - 1) + kth_smallest(xs, mid)) / 2.0;
}

fn pascal(n: Int) -> [Int] {
    let mut row: [Int] = [1];
    let mut k = 0;
    while k < n {
        row.push(row[k] * (n - k) / (k + 1));
        k = k + 1;
    }
    return row;
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Copy and insertion-sort by start (avoids assuming a stdlib sort).
    let mut a: [(Int, Int)] = xs;
    let mut i: Int = 1;
    while i < a.len() {
        let cur: (Int, Int) = a[i];
        let mut j: Int = i;
        while j > 0 && a[j - 1].0 > cur.0 {
            a[j] = a[j - 1];
            j = j - 1;
        }
        a[j] = cur;
        i = i + 1;
    }

    // Sweep through the sorted intervals, merging overlapping or touching ones.
    let mut out: [(Int, Int)] = [];
    let mut k: Int = 0;
    while k < a.len() {
        let s: Int = a[k].0;
        let e: Int = a[k].1;
        if out.len() > 0 && s <= out[out.len() - 1].1 {
            let last: Int = out.len() - 1;
            if e > out[last].1 {
                out[last] = (out[last].0, e);
            }
        } else {
            out.push((s, e));
        }
        k = k + 1;
    }
    return out;
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let mut result = fallback;
    for x in xs {
        result = x;
