    return result;
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let mut result: [(T, T)] = [];
    let mut i = 0;
    while i + 1 < xs.len() {
        result.push((xs[i], xs[i + 1]));
        i = i + 1;
    }
    return result;
}

