fn sum_squares(lo: Int, hi: Int) -> Int {
    let mut total = 0
    let mut i = lo
    while i <= hi {
        total = total + i * i
        i = i + 1
    }
    return total
}

fn squares(n: Int) -> Int ! Error {
    let mid = n / 2

    // Run both halves concurrently.
    let first = spawn sum_squares(1, mid)
    let rest = spawn sum_squares(mid + 1, n)

    // Wait for both tasks; propagate any task failure as an Error.
    let a = first.join()?
    let b = rest.join()?

    return a + b
}

