    }
    if n % 2 != 0 {
        return false;
    }
    return is_power_of_two(n / 2);
}

fn binary(n: Int) -> String {
    if n < 2 {
        if n == 0 {
            return "0"
        }
        return "1"
    }
    if n % 2 == 0 {
        return binary(n / 2) + "0"
    }
    return binary(n / 2) + "1"
}

fn mode(xs: [Int]) -> Int {
    var best = xs[0]
    var bestCount = 0
    for x in xs {
        var count = 0
        for y in xs {
            if y == x {
                count = count + 1
            }
        }
        if count > bestCount || (count == bestCount && x < best) {
            best = x
            bestCount = count
        }
    }
    return best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
