fn triangle(a: Int, b: Int, c: Int) -> String {
    if (a <= 0 || b <= 0 || c <= 0) {
        return "invalid";
    }
    if (a >= b + c || b >= a + c || c >= a + b) {
        return "invalid";
    }
    if (a == b && b == c) {
        return "equilateral";
    }
    if (a == b || b == c || a == c) {
        return "isosceles";
    }
    return "scalene";
}

