fn top(players: [Player], k: Int) -> [String] {
    // Stable insertion sort, descending by score:
    // a new player only moves ahead of strictly lower scores,
    // so ties keep their original order.
    var sorted: [Player] = []
    for p in players {
        var i = sorted.len()
        sorted.push(p)
        while i > 0 && sorted[i - 1].score < p.score {
            sorted[i] = sorted[i - 1]
            i = i - 1
        }
        sorted[i] = p
    }

    var names: [String] = []
    var j = 0
    while j < k && j < sorted.len() {
        names.push(sorted[j].name)
        j = j + 1
    }
    return names
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int] {
    let mut result: [Int] = [];
    for x in xs {
        if x < lo {
            result.push(lo);
        } else if x > hi {
