fn simulate(commands: [Int]) -> [Int] {
    var queue: [Int] = []
    var head = 0
    for c in commands {
        if c > 0 {
            queue.push(c)
        } else if c == 0 && head < queue.len() {
            head = head + 1
        }
    }
    var result: [Int] = []
    var i = head
    while i < queue.len() {
        result.push(queue[i])
        i = i + 1
    }
    return result
}

fn sum_evens(xs: [Int]) -> Int {
