fn factorial(n: Int) -> Int
    require n >= 0 and n <= 20
{
    let product = 1
    let i = 2
    while i <= n {
        product = product * i
        i += 1
    }
    product
}

fn fib(n: Int) -> Int
    require n >= 0
{
    let a = 0
    let b = 1
    let i = 1
    while i < n {
        const next = a + b
        a = b
        b = next
        i += 1
    }
    if n == 0 { 0 } else { b }
}

fn by_length(words: [String]) -> [String] {
    let longest = 0
    for word in words {
        if word.len() > longest {
            longest = word.len()
        }
    }
    const limit = longest + 1
    let sorted: [String] = []
    for size in 0..limit {
        for word in words {
            if word.len() == size {
                sorted.push(word)
            }
        }
    }
    sorted
}

fn dedupe(xs: [Int]) -> [Int] {
    let result: [Int] = []
    for x in xs {
        if not result.contains(x) {
            result += [x]
        }
    }
    result
}

fn total_area(rects: [Rect]) -> Float {
    let total: Float = 0.0
    for rect in rects {
