fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = "abcdefghijklmnopqrstuvwxyz".chars()
    const rotated = letters.skip(k) + letters.take(k)
    let out = ""
    for c in text.chars() {
        let piece = "{c}"
        let position = 0
        for letter in letters {
            if letter == c {
                for shifted in rotated.skip(position).take(1) {
                    piece = "{shifted}"
                }
            }
            position += 1
        }
        out = "{out}{piece}"
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let width = 0
    for row in m {
        width = row.len()
    }
    let result: [[Int]] = []
    for j in 0..width {
        let column: [Int] = []
        for row in m {
            column += row.skip(j).take(1)
        }
        result.push(column)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    let result: Int? = none
    if lo < xs.len() {
        if xs[lo] == target {
            result = lo
        }
    }
    result
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail MathError.DivideByZero
    }
    a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let groups: [String: [String]] = [:]
    let seen: [String] = []
    for word in words {
        const letter = word.slice(0, 1)
        if not seen.contains(letter) {
            seen += [letter]
            groups[letter] = words.filter(w => w.slice(0, 1) == letter)
        }
    }
    groups
}

fn running(xs: [Int]) -> [Int]
    ensure result.len() == xs.len()
{
    let out: [Int] = []
    let total = 0
    for x in xs {
        total += x
        out += [total]
    }
    out
