fn gcd(a: Int, b: Int) -> Int {
    let x = a
    let y = b
    while y != 0 {
        const r = x % y
        x = y
        y = r
    }
    x
}

fn map_char(ch: String, from: String, to: String) -> String {
    let position = -1
    let i = 0
    for c in from.chars() {
        if "{c}" == ch {
            position = i
        }
        i += 1
    }
    let mapped = ch
    let j = 0
    for c in to.chars() {
        if j == position {
            mapped = "{c}"
        }
        j += 1
    }
    mapped
}

fn title(text: String) -> String {
    const lower = "abcdefghijklmnopqrstuvwxyz"
    const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let result = ""
    let at_start = true
    for c in text.chars() {
        const ch = "{c}"
        const mapped = if at_start {
            map_char(ch, lower, upper)
        } else {
            map_char(ch, upper, lower)
        }
        result = "{result}{mapped}"
        at_start = ch == " "
    }
    result
}

fn is_prime(n: Int) -> Bool {
    let prime = n >= 2
    let i = 2
    while prime and i <= n / i {
        if n % i == 0 {
            prime = false
        }
        i += 1
    }
    prime
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        let d = 2
        while is_prime and d * d <= candidate {
            if candidate % d == 0 {
                is_prime = false
            }
            d += 1
        }
        if is_prime {
            primes += [candidate]
        }
        candidate += 1
    }
    primes
}

fn digit_sum(n: Int) -> Int
    require n >= 0
{
    let rest = n
    let total = 0
    while rest > 0 {
        const quotient = rest / 10
        total += rest - quotient * 10
        rest = quotient
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    for c in text.chars() {
        const ch = "{c}"
        if count > 0 and ch == current {
            count += 1
        } else {
            if count > 0 {
                result = "{result}{current}{count}"
            }
            current = ch
            count = 1
        }
    }
    if count > 0 {
        result = "{result}{current}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for c in text.chars() {
        if c == "(" {
            stack.push(")")
        } else if c == "[" {
            stack.push("]")
        } else if c == "\{" {
            stack.push("}")
        } else if c == ")" or c == "]" or c == "}" {
            const top = stack.pop() ?? ""
            if top != c {
                ok = false
                break
            }
        }
    }
    ok and (stack.len() == 0)
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let result: (Int, Int)? = none
    let i = 0
    outer: for a in xs {
        let j = i + 1
        for b in xs.skip(j) {
            if a + b == target {
                result = (i, j)
                break outer
            }
            j += 1
        }
        i += 1
    }
    result
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const numerals = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    let remaining = n
    let result = ""
    for (value, symbol) in numerals {
        while remaining >= value {
            result = "{result}{symbol}"
            remaining -= value
        }
    }
    result
}

