}

// Longest text that both a and b start with.
fn shared_prefix(a: String, b: String) -> String {
    // Every prefix of a, shortest first.
    let candidates = [""]
    let built = ""
    for c in a.chars() {
        built = "{built}{c}"
        candidates.push(built)
    }

    // Grow a prefix of b while it is still a prefix of a.
    let best = ""
    let current = ""
    for c in b.chars() {
        current = "{current}{c}"
        if not candidates.contains(current) {
            break
        }
        best = current
    }
    best
}

fn second_largest(xs: [Int]) -> Int? {
    let has_largest = false
    let largest = 0
    let result: Int? = none
    for x in xs {
        if not has_largest {
            has_largest = true
            largest = x
        } else if x > largest {
            result = largest
            largest = x
        } else if x < largest {
            const current = result ?? x
            if x >= current {
                result = x
            }
        }
    }
    result
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let merged: [Int] = []
    let taken = 0
    for y in b {
        let position = 0
        for x in a {
            if position == taken {
                if x <= y {
                    merged.push(x)
                    taken += 1
                } else {
                    break
                }
            }
            position += 1
        }
        merged.push(y)
    }
    let seen = 0
    for x in a {
        if seen >= taken {
            merged.push(x)
        }
        seen += 1
    }
    merged
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()

    // prev[j] = distance between the empty prefix of a and the first j chars of b
    let prev = [0]
    let k = 0
    while k < ys.len() {
        k += 1
        prev.push(k)
    }

    let i = 0
    for ca in xs {
        i += 1
        let cur = [i]
        let left = i
        let j = 0
        for cb in ys {
            const cost = if ca == cb { 0 } else { 1 }
            let best = prev[j] + cost
            const up = prev[j + 1] + 1
            if up < best {
                best = up
            }
            if left + 1 < best {
                best = left + 1
            }
            cur.push(best)
            left = best
            j += 1
        }
        prev = cur
    }

    prev[ys.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        let rest = self.items
        const _ = rest.pop()
        Stack(items: rest)
    }

    fn top(self) -> Int? {
        let copy = self.items
        copy.pop()
    }
}

