fn median(xs: [Float]) -> Float
    require xs.len() > 0
{
    let sorted: [Float] = []
    for x in xs {
        const at = sorted.count(y => y <= x)
        sorted = sorted.take(at) + [x] + sorted.skip(at)
    }

    const n = sorted.len()
    const start = (n - 1) / 2
    const width = 2 - n % 2
    const middle = sorted.skip(start).take(width)

    let total = 0.0
    for value in middle {
        total += value
    }
    total / Float(width)
}

