fn insert_by_start(ordered: [(Int, Int)], start: Int, end: Int) -> [(Int, Int)] {
    let out: [(Int, Int)] = []
    let placed = false
    for (s, e) in ordered {
        if not placed and start < s {
            out.push((start, end))
            placed = true
        }
        out.push((s, e))
    }
    if not placed {
        out.push((start, end))
    }
    out
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let ordered: [(Int, Int)] = []
    for (s, e) in xs {
        ordered = insert_by_start(ordered, s, e)
    }

    let merged: [(Int, Int)] = []
    let started = false
    let cur_start = 0
    let cur_end = 0
    for (s, e) in ordered {
        if not started {
            cur_start = s
            cur_end = e
            started = true
        } else {
            if s <= cur_end {
                if e > cur_end {
                    cur_end = e
                }
            } else {
                merged.push((cur_start, cur_end))
                cur_start = s
                cur_end = e
            }
        }
    }
    if started {
        merged.push((cur_start, cur_end))
    }
    merged
}

