fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 {
        "invalid"
    } else {
        // All sides are positive here, so the subtractions cannot overflow.
        // a - b >= c is the same as a >= b + c.
        if a - b >= c or b - c >= a or c - a >= b {
            "invalid"
        } else {
            if a == b and b == c {
                "equilateral"
            } else {
                if a == b or b == c or a == c {
                    "isosceles"
                } else {
                    "scalene"
                }
            }
        }
    }
}

