fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = "abcdefghijklmnopqrstuvwxyz".chars()
    const shifted = letters.skip(k) + letters.take(k)
    let out = ""
    for c in text.chars() {
        let index = -1
        let i = 0
        for letter in letters {
            if letter == c {
                index = i
            }
            i += 1
        }
        let ch = c
        let j = 0
        for letter in shifted {
            if j == index {
                ch = letter
            }
            j += 1
        }
        out = "{out}{ch}"
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let width = 0
    for row in m {
        width = row.len()
    }
    let result: [[Int]] = []
    let c = 0
    while c < width {
        let column: [Int] = []
        for row in m {
            let j = 0
            for value in row {
                if j == c {
                    column.push(value)
                }
                j += 1
            }
        }
        result.push(column)
        c += 1
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    let found: Int? = none
    if lo < xs.len() {
        if xs[lo] == target {
            found = lo
        }
    }
    found
}

