fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        for p in primes {
            if p * p > candidate {
                break
            }
            if candidate % p == 0 {
                is_prime = false
                break
            }
        }
        if is_prime {
            primes.push(candidate)
        }
        candidate += 1
    }
    primes
}

