}

fn anagrams(a: String, b: String) -> Bool {
    const xs = fold_case(a).chars()
    const ys = fold_case(b).chars()
    let same = xs.len() == ys.len()
    for c in xs {
        const in_a = xs.count(x => x == c)
        const in_b = ys.count(y => y == c)
        if in_a != in_b {
            same = false
        }
    }
    same
}

fn flatten(xss: [[Int]]) -> [Int] {
    let result: [Int] = []
    for xs in xss {
        result += xs
    }
    result
}

fn chunks(xs: [Int], n: Int) -> [[Int]]
    require n >= 1
{
    let result: [[Int]] = []
    let current: [Int] = []
    for x in xs {
        current.push(x)
        if current.len() == n {
            result.push(current)
            current = []
        }
    }
    if current.len() > 0 {
        result.push(current)
    }
    result
}

fn rotate(xs: [Int], k: Int) -> [Int]
    require k >= 0
{
    if xs.len() == 0 {
        xs
    } else {
        const n = k % xs.len()
        xs.skip(n) + xs.take(n)
    }
}

fn prefixes(text: String) -> [String] {
    let out = [""]
    let current = ""
    for c in text.chars() {
        current = "{current}{c}"
        out.push(current)
    }
    out
}

fn shared_prefix(a: String, b: String) -> String {
    const known = prefixes(a)
    let best = ""
    for candidate in prefixes(b) {
        if known.contains(candidate) {
            best = candidate
        }
    }
    best
}

fn common_prefix(words: [String]) -> String {
    let started = false
    let prefix = ""
    for word in words {
        if started {
            prefix = shared_prefix(prefix, word)
        } else {
            prefix = word
            started = true
        }
    }
    prefix
}

fn second_largest(xs: [Int]) -> Int? {
    let largest = 0
    let second = 0
    let seen = 0
    for x in xs {
        if seen == 0 {
            largest = x
            seen = 1
        } else if x > largest {
            second = largest
            largest = x
            seen = 2
        } else if x < largest and (seen == 1 or x > second) {
            second = x
            seen = 2
        }
    }
    let result: Int? = none
    if seen == 2 {
        result = second
    }
    result
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let taken = 0
    for x in a {
        for y in b.skip(taken) {
            if y < x {
                result += [y]
                taken += 1
            } else {
                break
            }
        }
        result += [x]
    }
    result + b.skip(taken)
}

fn smaller(x: Int, y: Int) -> Int {
    if x < y { x } else { y }
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    const width = ys.len() + 1

    let prev = [0]
    for j in 1..width {
        prev += [j]
    }

    let i = 0
    for x in xs {
        i += 1
        let cur = [i]
        let j = 0
        for y in ys {
            const cost = if x == y { 0 } else { 1 }
            const deletion = prev[j + 1] + 1
            const insertion = cur[j] + 1
            const substitution = prev[j] + cost
            cur += [smaller(smaller(deletion, insertion), substitution)]
            j += 1
        }
        prev = cur
    }

    prev[ys.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        let rest = self.items
        const _ = rest.pop()
        Stack(items: rest)
    }

    fn top(self) -> Int? {
        let rest = self.items
        rest.pop()
    }
}

fn count_char(text: String, c: Char) -> Int {
    text.chars().count(ch => ch == c)
}

fn kth_smallest(xs: [Float], k: Int) -> Float
    require xs.len() > 0
    require k >= 0 and k < xs.len()
{
    // The k-th smallest (0-based) is the value x with
    // count(< x) <= k < count(<= x).
    xs.find(x => xs.count(y => y < x) <= k and k < xs.count(y => y <= x)) ?? 0.0
}

fn median(xs: [Float]) -> Float
    require xs.len() > 0
    example median([3.0, 1.0, 2.0]) == 2.0
    example median([4.0, 1.0, 3.0, 2.0]) == 2.5
{
    const n = xs.len()
    const mid = n / 2
    if n % 2 == 1 {
        kth_smallest(xs, mid)
    } else {
        (kth_smallest(xs, mid - 1) + kth_smallest(xs, mid)) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row: [Int] = [1]
    let value = 1
    let k = 0
    while k < n {
        value = value * (n - k) / (k + 1)
        row.push(value)
        k += 1
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // `merged` is kept sorted by start and fully disjoint (no touching) at all times.
    let merged: [(Int, Int)] = []
    for (s, e) in xs {
        let lo = s
        let hi = e
        let before: [(Int, Int)] = []
        let after: [(Int, Int)] = []
        for (a, b) in merged {
            if b < lo {
                before.push((a, b))
            } else {
                if a > hi {
                    after.push((a, b))
                } else {
                    // Overlaps or touches: absorb into the interval being inserted.
                    if a < lo {
                        lo = a
                    }
                    if b > hi {
                        hi = b
                    }
                }
            }
        }
        before.push((lo, hi))
        merged = before + after
    }
    merged
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let result = fallback
    for x in xs {
        result = x
    }
    result
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let result: [(T, T)] = []
    let prev: T? = none
    for x in xs {
        if let p = prev {
            result.push((p, x))
        }
        prev = x
    }
    result
}

