fn port_sum(text: String) -> Int ! PortError {
    let parts = text.split(":")
    if parts.len() != 2 {
        fail PortError.Bad(text: text)
    }
    const second = parts.pop() ?? ""
    const first = parts.pop() ?? ""
    const a = try parse_port(first)
    const b = try parse_port(second)
    a + b
}

fn sum_squares(first: Int, last: Int) -> Int {
    let total = 0
    let i = first
    while i <= last {
        total += i * i
        i += 1
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const low = spawn sum_squares(1, mid)
    const high = spawn sum_squares(mid + 1, n)
    const a = try low.wait()
    const b = try high.wait()
    a + b
}

fn total_qty(text: String) -> Int {
