fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let keys: [String] = []
    for (key, value) in m {
        if value >= min {
            const i = keys.count(k => k < key)
            keys = keys.take(i) + [key] + keys.skip(i)
        }
    }
    keys
}

fn numbered(items: [String]) -> String {
