fn is_power_of_two(n: Int) -> Bool {
    let x = n
    while x > 1 and (x / 2) * 2 == x {
        x = x / 2
    }
    x == 1
}

fn binary(n: Int) -> String
    require n >= 0
{
    let digits = ""
    let rest = n
    while rest > 0 {
        digits = "{rest % 2}{digits}"
        rest = rest / 2
    }
    if n == 0 { "0" } else { digits }
}

fn mode(xs: [Int]) -> Int
    require xs.len() > 0
{
    let best = 0
    let best_count = 0
    for x in xs {
        let c = 0
        for y in xs {
            if y == x {
                c += 1
            }
        }
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    const n = if keys.len() < values.len() { keys.len() } else { values.len() }
    let i = 0
    while i < n {
        result[keys[i]] = values[i]
        i += 1
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 {
        "invalid"
    } else if a - b >= c or b - c >= a or c - a >= b {
        "invalid"
    } else if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn lengths(text: String) -> [Int] {
