fn collatz(n: Int) -> Int
    require n >= 1
{
    let current = n
    let steps = 0
    while current != 1 {
        current = if current % 2 == 0 { current / 2 } else { 3 * current + 1 }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int
    ensure result >= 0
{
    const digits = "0123456789".chars()
    let total = 0
    for c in text.chars() {
        let value = 0
        for d in digits {
            if c == d {
                total += value
            }
            value += 1
        }
    }
    total
