fn top(players: [Player], k: Int) -> [String] {
    let ranked: [Player] = []
    for player in players {
        let next: [Player] = []
        let placed = false
        for other in ranked {
            if not placed and other.score < player.score {
                next.push(player)
                placed = true
            }
            next.push(other)
        }
        if not placed {
            next.push(player)
        }
        ranked = next
    }
    let names: [String] = []
    for player in ranked {
        if names.len() >= k {
            break
        }
        names.push(player.name)
    }
    names
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    require lo <= hi
    ensure result.len() == xs.len()
{
    let out: [Int] = []
    for x in xs {
        let v = x
        if v < lo {
            v = lo
        }
        if v > hi {
            v = hi
        }
        out.push(v)
    }
    out
}

fn is_sorted(xs: [Int]) -> Bool {
