fn simulate(commands: [Int]) -> [Int] {
    let queue: [Int] = []
    let head = 0
    for command in commands {
        if command > 0 {
            queue += [command]
        }
        if command == 0 and head < queue.len() {
            head += 1
        }
    }
    queue.skip(head)
}

