fn by_length(words: [String]) -> [String] {
    const n = words.len()
    if n < 2 {
        return words
    }
    const mid = n / 2
    const left = by_length(words.take(mid))
    const right = by_length(words.skip(mid))
    let merged: [String] = []
    let i = 0
    let j = 0
    while i < left.len() and j < right.len() {
        if right[j].len() < left[i].len() {
            merged.push(right[j])
            j += 1
        } else {
            merged.push(left[i])
            i += 1
        }
    }
    while i < left.len() {
        merged.push(left[i])
        i += 1
    }
    while j < right.len() {
        merged.push(right[j])
        j += 1
    }
    merged
}

fn dedupe(xs: [Int]) -> [Int]
    example dedupe([1, 2, 1, 3, 2]) == [1, 2, 3]
    example dedupe([]) == []
{
    let seen: Set<Int> = Set.of()
    let out: [Int] = []
    for x in xs {
        if not seen.contains(x) {
            seen.add(x)
            out.push(x)
        }
    }
    out
}

