fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
    example caesar("abc", 1) == "bcd"
    example caesar("xyz", 3) == "abc"
    example caesar("Hello, World!", 0) == "Hello, World!"
{
    const alphabet = "abcdefghijklmnopqrstuvwxyz".chars()
    let out: [String] = []
    for c in text.chars() {
        let found = -1
        for i in 0..26 {
            if alphabet[i] == c {
                found = i
                break
            }
        }
        if found >= 0 {
            out.push("{alphabet[(found + k) % 26]}")
        } else {
            out.push("{c}")
        }
    }
    out.join("")
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let result: [[Int]] = []
    if m.len() == 0 {
        return result
    }
    const cols = m[0].len()
    for j in 0..cols {
        let column: [Int] = []
        for row in m {
            column.push(row[j])
        }
        result.push(column)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        const value = xs[mid]
        if value == target {
            return mid
        }
        if value < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    none
}

